    11	
    12	// Opening a fifo for reading blocks until someone opens the write end, so a
    13	// fifo where the lock file should be would hang the very error path whose job
    14	// is to report that we have already waited long enough. It must be refused
    15	// without being opened.
    16	func TestLockHolderDescriptionNeverBlocksOnAFifo(t *testing.T) {
    17		t.Parallel()
    18		path := filepath.Join(t.TempDir(), "write.lock")
    19		if err := syscall.Mkfifo(path+fileLockOwnerSuffix, 0o600); err != nil {
    20			t.Skipf("mkfifo unavailable: %v", err)
    21		}
    22		done := make(chan string, 1)
    23		go func() { done <- describeFileLockHolder(path) }()
    24		select {
    25		case got := <-done:
    26			if got != "" {
    27				t.Fatalf("a fifo must describe no holder, got %q", got)
    28			}
    29		case <-time.After(10 * time.Second):
    30			t.Fatal("describeFileLockHolder blocked on a fifo")
    31		}
    32	}
