    48		firstAcquired := make(chan struct{})
    49		firstDone := make(chan struct{})
    50		secondAcquired := make(chan struct{})
    51		releaseFirst := make(chan struct{})
    52		var shared int
    53		var wait sync.WaitGroup
    54	
    55		wait.Add(1)
    56		go func() {
    57			defer wait.Done()
    58			defer close(firstDone)
    59			lock, err := acquireFileLock(lockPath, "brain_locked", time.Second)
    60			if err != nil {
    61				t.Errorf("first acquire: %v", err)
    62				return
    63			}
    64			defer func() {
    65				if err := lock.Close(); err != nil {
    66					t.Errorf("first release: %v", err)
    67				}
    68			}()
    69			close(firstAcquired)
    70			<-releaseFirst
    71			shared++
