    79			case <-firstDone:
    80				return
    81			}
    82			lock, err := acquireFileLock(lockPath, "brain_locked", time.Second)
    83			if err != nil {
    84				t.Errorf("second acquire: %v", err)
    85				return
    86			}
    87			defer func() {
    88				if err := lock.Close(); err != nil {
    89					t.Errorf("second release: %v", err)
    90				}
    91			}()
    92			close(secondAcquired)
    93			shared++
    94		}()
    95	
    96		earlySecond := false
    97		select {
    98		case <-secondAcquired:
    99			earlySecond = true
   100		case <-firstDone:
   101		case <-time.After(50 * time.Millisecond):
   102		}
   103		close(releaseFirst)
