    61	// gitHardenRepo builds a repository with one committed file that has been
    62	// modified in the worktree without changing its size. Equal sizes force git to
    63	// re-read and re-hash the file rather than shortcutting on stat data, which is
    64	// what makes the clean-filter and fsmonitor paths reachable.
    65	func gitHardenRepo(t *testing.T) string {
    66		t.Helper()
    67		dir := t.TempDir()
    68		// --template= starts .git/hooks empty. Without it a developer whose
    69		// init.templateDir ships executable hooks would get them copied into every
    70		// fixture repository, where they are neither this test's payload nor
    71		// something the assertions can account for.
    72		gitHardenRun(t, dir, "init", "-q", "--template=", ".")
    73		gitHardenRun(t, dir, "config", "user.name", "Entire Brain Test")
    74		gitHardenRun(t, dir, "config", "user.email", "brain-test@example.invalid")
    75		gitHardenRun(t, dir, "config", "commit.gpgsign", "false")
    76		if err := os.WriteFile(filepath.Join(dir, "a.txt"), []byte("hello\nworld\n"), 0o644); err != nil {
    77			t.Fatal(err)
    78		}
    79		gitHardenRun(t, dir, "add", "-A")
    80		gitHardenRun(t, dir, "commit", "-qm", "init")
    81		if err := os.WriteFile(filepath.Join(dir, "a.txt"), []byte("HELLO\nWORLD\n"), 0o644); err != nil {
    82			t.Fatal(err)
    83		}
    84		return dir
    85	}
