    87	// gitHardenPayload writes an executable script that records the fact it ran by
    88	// creating sentinel, then behaves like a well-mannered filter so the arming
    89	// itself does not break the command under test.
    90	func gitHardenPayload(t *testing.T) (script, sentinel string) {
    91		t.Helper()
    92		dir := t.TempDir()
    93		sentinel = filepath.Join(dir, "PWNED")
    94		script = filepath.Join(dir, "payload.sh")
    95		body := "#!/bin/sh\ntouch " + sentinel + "\nif [ -f \"$1\" ]; then cat \"$1\"; fi\nexit 0\n"
    96		if err := os.WriteFile(script, []byte(body), 0o755); err != nil {
    97			t.Fatal(err)
    98		}
    99		return script, sentinel
   100	}
