   102	func gitHardenAssertClean(t *testing.T, sentinel, vector string) {
   103		t.Helper()
   104		if _, err := os.Stat(sentinel); err == nil {
   105			t.Fatalf("SECURITY: repo-local %s executed an attacker-controlled program during indexing", vector)
   106		} else if !os.IsNotExist(err) {
   107			t.Fatalf("stat sentinel: %v", err)
   108		}
   109	}
