   111	func TestWorktreeFingerprintDoesNotRunRepoLocalDiffExternal(t *testing.T) {
   112		gitHardenSkipUnsupported(t)
   113		repo := gitHardenRepo(t)
   114		payload, sentinel := gitHardenPayload(t)
   115		gitHardenRun(t, repo, "config", "diff.external", payload)
   116	
   117		ctx := context.Background()
   118		fingerprint, err := worktreeFingerprint(ctx, ExecRunner{}, repo)
   119		if err != nil {
   120			t.Fatalf("worktreeFingerprint: %v", err)
   121		}
   122		gitHardenAssertClean(t, sentinel, "diff.external")
   123		if fingerprint == "" {
   124			t.Fatal("empty fingerprint")
   125		}
   126	
   127		// diff.external also silently empties `git diff` output, so the fingerprint
   128		// stops seeing worktree content. Prove the diff survived neutralization.
   129		ignore, err := loadBrainIgnore(repo)
   130		if err != nil {
   131			t.Fatalf("loadBrainIgnore: %v", err)
   132		}
   133		diff, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore)
   134		if err != nil {
   135			t.Fatalf("gitDiffBinary: %v", err)
   136		}
   137		if !strings.Contains(string(diff), "a.txt") || !strings.Contains(string(diff), "HELLO") {
   138			t.Fatalf("diff.external degraded the worktree diff; got %q", string(diff))
   139		}
   140	}
