   242	// TestGitDiffBinaryDoesNotRunRepoLocalCleanFilter is the fourth vector.
   243	//
   244	// `git diff HEAD` compares the index/HEAD blob against the WORKTREE file, and
   245	// to do that git must run the content through the clean filter selected by
   246	// .gitattributes. So filter.<driver>.clean executes under the exact hardened
   247	// argv the other three vectors are neutralized by:
   248	//
   249	//	git -c core.fsmonitor=false diff --no-ext-diff --no-textconv --binary HEAD --
   250	//
   251	// Confirmed against git 2.54.0 before the fix. Neither --no-ext-diff nor
   252	// --no-textconv touches the filter machinery: they neutralize the diff drivers,
   253	// which are a different mechanism entirely.
   254	func TestGitDiffBinaryDoesNotRunRepoLocalCleanFilter(t *testing.T) {
   255		gitHardenSkipUnsupported(t)
   256		repo, sentinel := gitHardenFilterRepo(t, "pwn", "clean")
   257	
   258		ctx := context.Background()
   259		ignore, err := loadBrainIgnore(repo)
   260		if err != nil {
   261			t.Fatalf("loadBrainIgnore: %v", err)
   262		}
   263		diff, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore)
   264		if err != nil {
   265			t.Fatalf("gitDiffBinary: %v", err)
   266		}
   267		gitHardenAssertClean(t, sentinel, "filter.<driver>.clean")
   268		// The neutralizer must not cost the output either: a blanked clean filter
   269		// still has to produce the real worktree diff.
   270		if !strings.Contains(string(diff), "a.txt") || !strings.Contains(string(diff), "HELLO") {
   271			t.Fatalf("blanking the clean filter degraded the worktree diff; got %q", string(diff))
