   380	// TestGlobalFilterDriversAreLeftAlone draws the trust boundary.
   381	//
   382	// The finding is that a REPOSITORY must not be able to make git run code. A
   383	// driver configured in the user's own ~/.gitconfig is not the repository's
   384	// code, it is the user's — `git lfs install` puts filter.lfs.clean there — and
   385	// blanking it would silently corrupt every diff of an LFS repository (git would
   386	// compare a real worktree file against a stored pointer). So only local and
   387	// worktree scope, the scopes the repository itself carries, are neutralized.
   388	func TestGlobalFilterDriversAreLeftAlone(t *testing.T) {
   389		gitHardenSkipUnsupported(t)
   390		repo := gitHardenRepo(t)
   391		overrides := repoFilterDriverOverrides(context.Background(), repo)
   392		if len(overrides) != 0 {
   393			t.Fatalf("a repository with no local filter driver produced overrides: %v", overrides)
   394		}
   395	
   396		gitHardenRun(t, repo, "config", "--local", "filter.local-one.clean", "cat")
   397		overrides = repoFilterDriverOverrides(context.Background(), repo)
   398		var keys []string
   399		for _, o := range overrides {
   400			keys = append(keys, o.Key)
   401		}
   402		for _, want := range []string{
   403			"filter.local-one.clean", "filter.local-one.smudge",
   404			"filter.local-one.process", "filter.local-one.required",
   405		} {
   406			if !slices.Contains(keys, want) {
   407				t.Fatalf("local driver not fully neutralized: %q missing from %v", want, keys)
   408			}
   409		}
   410	}
