    30				name: "flags land before the pathspec separator",
    31				in:   []string{"diff", "--cached", "--binary", "HEAD", "--", ".", ":(exclude).env"},
    32				want: gitHardenWant("diff", "--no-ext-diff", "--no-textconv", "--cached", "--binary", "HEAD", "--", ".", ":(exclude).env"),
