    97			{"-c", "core.quotepath=false", "log", "--no-merges", "--format=%H"},
    98			{"log", "--no-walk", "--format=%H"},
    99			{"log", "--first-parent", "--format=%H", "--max-count=10", "main"},
   100			{"rev-list", "--count", "--first-parent", "main"},
   101			{"ls-files"},
