    15	
    16	// The tests below encode a code-execution finding: git resolves several
    17	// configuration keys to commands it executes, and it honours them from the
    18	// per-repository .git/config (and in-tree .gitattributes) of whatever
    19	// repository it is pointed at. Indexing an untrusted repository must never run
    20	// code that repository carries.
    21	//
    22	// Every case builds a real repository, arms one vector with a script that
    23	// touches a sentinel file, drives a production code path with the real
    24	// ExecRunner, and asserts both that the sentinel was NOT created and that the
    25	// command still produced correct output (a neutralizer that breaks the output
    26	// silently corrupts the worktree fingerprint, which is its own bug).
    27	
    28	func gitHardenSkipUnsupported(t *testing.T) {
    29		t.Helper()
    30		if runtime.GOOS == "windows" {
    31			t.Skip("sentinel payloads are POSIX shell scripts")
    32		}
    33		if _, err := exec.LookPath("git"); err != nil {
    34			t.Skip("git is not installed")
    35		}
    36	}
    37	
    38	// gitHardenRun runs one of the fixture's OWN git commands. It turns hooks off
    39	// for that invocation only, on argv, because `git init` copies whatever
    40	// init.templateDir holds into .git/hooks and a developer with a global
    41	// core.hooksPath would otherwise have their real pre-commit run inside a
    42	// fixture repository.
    43	//
    44	// The suppression used to be written into the fixture repository's config
    45	// instead (`git config core.hooksPath <dir>/.no-hooks`), which disarmed hooks
    46	// for the CODE UNDER TEST as well. Every hardening test therefore ran against a
    47	// repository where the hook vector was already neutralized by the fixture, so
    48	// the suite was structurally incapable of noticing that nothing in the product
    49	// neutralized it -- and it did not, until gitHardenConfig gained core.hooksPath.
    50	// Keeping the flag on argv covers the test's own scaffolding and nothing else,
    51	// which is what lets the hook tests below drive production code at a live hook.
    52	func gitHardenRun(t *testing.T, dir string, args ...string) {
    53		t.Helper()
    54		cmd := exec.Command("git", append([]string{"-c", "core.hooksPath=" + gitHooksDisabledPath}, args...)...)
    55		cmd.Dir = dir
    56		if out, err := cmd.CombinedOutput(); err != nil {
    57			t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
    58		}
    59	}
    60	
    61	// gitHardenRepo builds a repository with one committed file that has been
    62	// modified in the worktree without changing its size. Equal sizes force git to
    63	// re-read and re-hash the file rather than shortcutting on stat data, which is
    64	// what makes the clean-filter and fsmonitor paths reachable.
    65	func gitHardenRepo(t *testing.T) string {
    66		t.Helper()
    67		dir := t.TempDir()
    68		// --template= starts .git/hooks empty. Without it a developer whose
    69		// init.templateDir ships executable hooks would get them copied into every
    70		// fixture repository, where they are neither this test's payload nor
    71		// something the assertions can account for.
    72		gitHardenRun(t, dir, "init", "-q", "--template=", ".")
    73		gitHardenRun(t, dir, "config", "user.name", "Entire Brain Test")
    74		gitHardenRun(t, dir, "config", "user.email", "brain-test@example.invalid")
    75		gitHardenRun(t, dir, "config", "commit.gpgsign", "false")
    76		if err := os.WriteFile(filepath.Join(dir, "a.txt"), []byte("hello\nworld\n"), 0o644); err != nil {
    77			t.Fatal(err)
    78		}
    79		gitHardenRun(t, dir, "add", "-A")
    80		gitHardenRun(t, dir, "commit", "-qm", "init")
    81		if err := os.WriteFile(filepath.Join(dir, "a.txt"), []byte("HELLO\nWORLD\n"), 0o644); err != nil {
    82			t.Fatal(err)
    83		}
    84		return dir
    85	}
    86	
    87	// gitHardenPayload writes an executable script that records the fact it ran by
    88	// creating sentinel, then behaves like a well-mannered filter so the arming
    89	// itself does not break the command under test.
    90	func gitHardenPayload(t *testing.T) (script, sentinel string) {
    91		t.Helper()
    92		dir := t.TempDir()
    93		sentinel = filepath.Join(dir, "PWNED")
    94		script = filepath.Join(dir, "payload.sh")
    95		body := "#!/bin/sh\ntouch " + sentinel + "\nif [ -f \"$1\" ]; then cat \"$1\"; fi\nexit 0\n"
    96		if err := os.WriteFile(script, []byte(body), 0o755); err != nil {
    97			t.Fatal(err)
    98		}
    99		return script, sentinel
   100	}
