   526	// gitHardenRequireLiveHook proves the arming fires before anything is asserted
   527	// about it. Without this control a hook test that silently stopped arming
   528	// anything -- a git change, a coarse-grained filesystem -- would keep passing
   529	// while defending nothing.
   530	func gitHardenRequireLiveHook(t *testing.T, repo, log string) {
   531		t.Helper()
