   111			{"clone", "--quiet", "--", "https://example.invalid/r.git", "d"},
   112			{"fetch", "--quiet", "origin", "refs/heads/entire/*:refs/heads/entire/*"},
   113		}
   114		for _, args := range invocations {
   115			got := hardenedGitArgs(args...)
   116			if len(got) < len(gitHardenConfig) || !slices.Equal(got[:len(gitHardenConfig)], gitHardenConfig) {
   117				t.Errorf("%q: missing the hardening config prefix, got %q", args, got)
   118			}
   119			sub := args[gitSubcommandIndex(args)]
   120			if gitHardenDiffFamily[sub] {
   121				for _, flag := range gitHardenDiffFlags {
   122					if !slices.Contains(got, flag) {
   123						t.Errorf("%q: diff-family invocation missing %s, got %q", args, flag, got)
   124					}
   125				}
   126			}
   127		}
