   130	// A repository controls .brainignore, and .brainignore feeds exclusion
   131	// pathspecs into gitDiffBinary. A pathspec that spells a neutralizer flag must
   132	// not be mistaken for the caller having already passed it.
   133	func TestHardenedGitArgsIgnoresPathspecsWhenDeduplicating(t *testing.T) {
   134		t.Parallel()
   135		got := hardenedGitArgs("diff", "--binary", "HEAD", "--", ".", "--no-ext-diff", "--no-textconv")
   136		want := gitHardenWant(
   137			"diff", "--no-ext-diff", "--no-textconv",
   138			"--binary", "HEAD", "--", ".", "--no-ext-diff", "--no-textconv",
   139		)
   140		if !slices.Equal(got, want) {
   141			t.Fatalf("neutralizer suppressed by a pathspec\n got %q\nwant %q", got, want)
   142		}
   143	}
