   145	// TestGitHardenConfigIsPinned spells the prefix out in full, because every other
   146	// expectation in this file is derived from it. Losing a neutralizer has to fail
   147	// a test rather than quietly rewrite what the suite expects.
   148	func TestGitHardenConfigIsPinned(t *testing.T) {
   149		t.Parallel()
   150		want := []string{
   151			"-c", "core.fsmonitor=false",
   152			"-c", "core.hooksPath=/dev/null/entire-brain-hooks-disabled",
   153		}
   154		if !slices.Equal(gitHardenConfig, want) {
   155			t.Fatalf("the hardening prefix changed\n got %q\nwant %q", gitHardenConfig, want)
