     1	package cli
     2	
     3	import (
     4		"regexp"
     5		"strings"
     6		"testing"
     7	
     8		"github.com/spf13/cobra"
     9	)
    10	
    11	// `guide` is the command set an agent is told to work from — it is the FIRST
    12	// thing a coding agent reads about this tool, and every line in it is a promise
    13	// that the line can be typed. Nothing checked that. The guide is a hand-written
    14	// string literal, so a renamed flag or a subcommand moved under a different
    15	// parent silently turns it into instructions for a tool that no longer exists,
    16	// and an agent that follows it gets "unknown command" instead of an answer.
    17	//
    18	// This does not pin the guide's wording. It extracts every `entire brain …`
    19	// invocation the guide prints, resolves the verbs against the real command tree
    20	// and every long flag against that command's real flag set. Rewrite the guide
    21	// however you like; you may not advertise something that is not there.
    22	
    23	// guideInvocation matches an indented command line in the guide body.
    24	var guideInvocation = regexp.MustCompile(`(?m)^\s+entire brain ([^\n#]+)`)
    25	
    26	// guideCommandLines returns the guide's invocations, each already split into
    27	// tokens with the trailing comment removed.
    28	func guideCommandLines(t *testing.T) [][]string {
    29		t.Helper()
    30		t.Chdir(t.TempDir()) // Standalone reference; never inspect real plugin state.
    31		out, err := execute(t, NewRootCommand(Options{Version: "test"}), "agent-guide")
    32		if err != nil {
    33			t.Fatalf("guide: %v", err)
    34		}
    35		var lines [][]string
    36		for _, match := range guideInvocation.FindAllStringSubmatch(out, -1) {
    37			if fields := strings.Fields(match[1]); len(fields) > 0 {
    38				lines = append(lines, fields)
    39			}
    40		}
    41		if len(lines) < 20 {
    42			t.Fatalf("only %d invocations found in the guide — the extraction is broken, not the guide", len(lines))
    43		}
    44		return lines
    45	}
    46	
    47	// guidePlaceholder reports whether a token is a documentation placeholder
    48	// (`<query>`, `[repo]`, `"<task>"`, `<id>...`) rather than a real operand.
    49	func guidePlaceholder(token string) bool {
    50		trimmed := strings.Trim(token, `"'`)
    51		return strings.HasPrefix(trimmed, "<") || strings.HasPrefix(trimmed, "[")
    52	}
    53	
    54	// guideResolvePath walks a guide invocation's leading tokens against the real
    55	// command tree and returns the command it names, plus the tokens consumed. A
    56	// token is only treated as a subcommand while the command reached so far HAS
    57	// subcommands; once a leaf is reached the rest are operands
    58	// (`inspect graph-ui semantic-graph.html`), not a misspelled verb. That
    59	// distinction is the whole point: an operand must be ignored, a verb that does
    60	// not exist must fail.
    61	func guideResolvePath(t *testing.T, root *cobra.Command, tokens []string) (*cobra.Command, bool) {
    62		t.Helper()
    63		cmd := root
    64		consumed := 0
    65		for _, token := range tokens {
    66			if strings.HasPrefix(token, "-") || guidePlaceholder(token) {
    67				break
    68			}
    69			if consumed > 0 && !cmd.HasSubCommands() {
    70				break // a leaf command: everything left is an operand
    71			}
    72			next := guideSubcommand(cmd, token)
    73			if next == nil {
    74				t.Errorf("guide advertises `entire brain %s`, but %q is not a command under %q",
    75					strings.Join(tokens, " "), token, cmd.CommandPath())
    76				return nil, false
    77			}
    78			cmd, consumed = next, consumed+1
    79		}
    80		if consumed == 0 {
    81			t.Errorf("guide line %q names no command", strings.Join(tokens, " "))
    82			return nil, false
    83		}
    84		return cmd, true
    85	}
    86	
    87	// guideSubcommand finds a direct subcommand by name or alias.
    88	func guideSubcommand(parent *cobra.Command, name string) *cobra.Command {
    89		for _, sub := range parent.Commands() {
    90			if sub.Name() == name {
    91				return sub
    92			}
    93			for _, alias := range sub.Aliases {
    94				if alias == name {
    95					return sub
    96				}
    97			}
    98		}
    99		return nil
   100	}
