    70		stones := sessionTombstones{Version: sessionTombstonesVersion, Excluded: map[string]sessionTombstone{
    71			excluded.SessionID: {At: time.Now().UTC()},
    72		}}
    73		guard := sessionReadGuard{ids: stones.Excluded, paths: excludedTranscriptPaths(manifest, stones)}
    74		packet := buildHandoffPacket(manifest, index, facts, "main", 5, time.Now().UTC(), guard)
    75		data, err := json.Marshal(packet)
    76		if err != nil {
