18	func FuzzReadMCPMessage(f *testing.F) {
19		f.Add([]byte("Content-Length: 2\r\n\r\n{}"))
20		f.Add([]byte(`{"jsonrpc":"2.0","id":1,"method":"initialize"}` + "\n"))
21		f.Add([]byte("Content-Length: -1\r\n\r\n"))
22		f.Add([]byte("Content-Length: 999999999\r\n\r\nshort"))
23		f.Fuzz(func(t *testing.T, data []byte) {
24			// May loop over multiple frames until EOF/error; bounded by input length.
25			r := bufio.NewReader(bytes.NewReader(data))
26			for i := 0; i < 64; i++ {
27				if _, _, err := readMCPMessage(r); err != nil {
28					return
29				}
30			}
31		})
32	}
