   275	// TestWorktreeFingerprintDoesNotRunRepoLocalCleanFilter drives the same vector
   276	// through the fingerprint path, which is what actually runs during indexing.
   277	func TestWorktreeFingerprintDoesNotRunRepoLocalCleanFilter(t *testing.T) {
