   291	// TestGitDiffBinaryDoesNotRunRepoLocalProcessFilter covers the sibling key.
   292	// filter.<driver>.process is a long-running protocol filter that SUPERSEDES
   293	// clean and smudge, so blanking only .clean would leave this arming live —
   294	// verified: with .clean blanked and .process armed, the payload still ran.
   295	func TestGitDiffBinaryDoesNotRunRepoLocalProcessFilter(t *testing.T) {
   296		gitHardenSkipUnsupported(t)
   297		repo, sentinel := gitHardenFilterRepo(t, "pwn", "process")
   298	
   299		ctx := context.Background()
   300		ignore, err := loadBrainIgnore(repo)
   301		if err != nil {
   302			t.Fatalf("loadBrainIgnore: %v", err)
   303		}
   304		if _, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore); err != nil {
   305			t.Fatalf("gitDiffBinary: %v", err)
   306		}
   307		gitHardenAssertClean(t, sentinel, "filter.<driver>.process")
