   310	// TestGitDiffBinaryDoesNotRunSmudgeFilter covers the third key. Smudge runs on
   311	// the checkout side rather than the diff side, so it is not reachable from
   312	// gitDiffBinary today; the assertion is that arming it changes nothing, which
   313	// keeps the neutralizer honest if a future call path does check content out.
   314	func TestGitDiffBinaryDoesNotRunSmudgeFilter(t *testing.T) {
   315		gitHardenSkipUnsupported(t)
   316		repo, sentinel := gitHardenFilterRepo(t, "pwn", "smudge")
   317	
   318		ctx := context.Background()
   319		ignore, err := loadBrainIgnore(repo)
   320		if err != nil {
   321			t.Fatalf("loadBrainIgnore: %v", err)
   322		}
   323		if _, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore); err != nil {
   324			t.Fatalf("gitDiffBinary: %v", err)
   325		}
   326		gitHardenAssertClean(t, sentinel, "filter.<driver>.smudge")
