   328	
   329	// TestRequiredCleanFilterDoesNotBreakTheRead: filter.<driver>.required=true
   330	// makes git ABORT ("fatal: ... clean filter 'x' failed") when the filter
   331	// command is blanked. A neutralizer that turns a code-execution bug into a
   332	// hard failure to index the repository has only traded one denial for another,
   333	// so required must be forced false alongside the command.
   334	func TestRequiredCleanFilterDoesNotBreakTheRead(t *testing.T) {
   335		gitHardenSkipUnsupported(t)
   336		repo, sentinel := gitHardenFilterRepo(t, "pwn", "clean")
   337		gitHardenRun(t, repo, "config", "filter.pwn.required", "true")
   338	
   339		ctx := context.Background()
   340		ignore, err := loadBrainIgnore(repo)
   341		if err != nil {
   342			t.Fatalf("loadBrainIgnore: %v", err)
   343		}
   344		diff, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore)
   345		if err != nil {
   346			t.Fatalf("a required filter broke the read instead of being neutralized: %v", err)
   347		}
   348		gitHardenAssertClean(t, sentinel, "filter.<driver>.clean (required)")
   349		if !strings.Contains(string(diff), "a.txt") {
   350			t.Fatalf("diff lost its content; got %q", string(diff))
   351		}
   352	}
   353	
   354	// TestCleanFilterWithAnEqualsInItsDriverNameIsNeutralized is why the
   355	// neutralizer is delivered through GIT_CONFIG_KEY_n/GIT_CONFIG_VALUE_n rather
   356	// than `-c`.
   357	//
   358	// A config subsection may contain "=", and .gitattributes may select it:
   359	// `[filter "na=me"]` armed by `* filter=na=me` executes. But `-c` splits its
   360	// argument at the FIRST "=", so `-c filter.na=me.clean=` sets the key
   361	// "filter.na" to the value "me.clean=" and the real driver is untouched.
   362	// Verified against git 2.54.0: the `-c` form fails to neutralize this and the
   363	// payload runs. The environment form keeps key and value in separate variables,
   364	// so no name can escape it.
   365	func TestCleanFilterWithAnEqualsInItsDriverNameIsNeutralized(t *testing.T) {
   366		gitHardenSkipUnsupported(t)
   367		repo, sentinel := gitHardenFilterRepo(t, "na=me", "clean")
   368	
   369		ctx := context.Background()
   370		ignore, err := loadBrainIgnore(repo)
   371		if err != nil {
   372			t.Fatalf("loadBrainIgnore: %v", err)
   373		}
   374		if _, err := gitDiffBinary(ctx, ExecRunner{}, repo, false, ignore); err != nil {
   375			t.Fatalf("gitDiffBinary: %v", err)
   376		}
   377		gitHardenAssertClean(t, sentinel, `filter."na=me".clean`)
   378	}
   379	
   380	// TestGlobalFilterDriversAreLeftAlone draws the trust boundary.
   381	//
   382	// The finding is that a REPOSITORY must not be able to make git run code. A
   383	// driver configured in the user's own ~/.gitconfig is not the repository's
   384	// code, it is the user's — `git lfs install` puts filter.lfs.clean there — and
   385	// blanking it would silently corrupt every diff of an LFS repository (git would
   386	// compare a real worktree file against a stored pointer). So only local and
   387	// worktree scope, the scopes the repository itself carries, are neutralized.
   388	func TestGlobalFilterDriversAreLeftAlone(t *testing.T) {
   389		gitHardenSkipUnsupported(t)
   390		repo := gitHardenRepo(t)
   391		overrides := repoFilterDriverOverrides(context.Background(), repo)
   392		if len(overrides) != 0 {
   393			t.Fatalf("a repository with no local filter driver produced overrides: %v", overrides)
   394		}
   395	
   396		gitHardenRun(t, repo, "config", "--local", "filter.local-one.clean", "cat")
   397		overrides = repoFilterDriverOverrides(context.Background(), repo)
   398		var keys []string
   399		for _, o := range overrides {
   400			keys = append(keys, o.Key)
   401		}
   402		for _, want := range []string{
   403			"filter.local-one.clean", "filter.local-one.smudge",
   404			"filter.local-one.process", "filter.local-one.required",
   405		} {
   406			if !slices.Contains(keys, want) {
   407				t.Fatalf("local driver not fully neutralized: %q missing from %v", want, keys)
   408			}
   409		}
   410	}
   411	
   412	// A FIFTH vector, and the cheapest of the five to arm: git HOOKS.
   413	//
   414	// The four above each need a config key, an in-tree .gitattributes entry, or
   415	// both. A hook needs neither: an executable file at .git/hooks/<name> is the
   416	// entire arming, and core.hooksPath merely relocates the directory for an
   417	// attacker who would rather also set a key. Nothing in the product read
   418	// core.hooksPath before gitHardenConfig did.
   419	//
   420	// post-index-change is the hook a read-only indexer reaches. git runs it
   421	// whenever a command REWRITES the index, and git rewrites the index when it
   422	// meets a tracked file whose cached stat data no longer matches the filesystem
   423	// but whose content still hashes to the indexed blob: it re-reads the file,
   424	// confirms the content, refreshes the stat cache, and writes the index back
   425	// out. `git status` does exactly that, and `git status` is the first thing the
   426	// worktree fingerprint runs.
   427	//
   428	// Measured against the unpatched binary on git 2.54.0, in a repository armed
   429	// with nothing but an executable hook file:
   430	//
   431	//	refresh --worktree --agent none   3 executions
   432	//	refresh --agent none              6
   433	//	status                            1
   434	//	status --verbose                  1
   435	//	overview                          1
   436	//
   437	// -- every one of them while the command exited 0 and reported "+ healthy".
   438	//
   439	// Only post-index-change is reachable while this binary merely reads. The
   440	// assertions below still cover the whole hook directory rather than that one
   441	// name, because the directory is the repository's and the neutralizer is not
   442	// hook-specific; a future call path that checks something out must not quietly
   443	// reopen the vector under a different hook name.
   444	
   445	const gitHardenHookName = "post-index-change"
   446	
   447	// gitHardenRunWithHooks is gitHardenRun without the hook suppression, for the
   448	// control that proves a test's arming actually fires. Using gitHardenRun here
   449	// would prove nothing: it disables the very hook being checked.
   450	func gitHardenRunWithHooks(t *testing.T, dir string, args ...string) {
   451		t.Helper()
   452		cmd := exec.Command("git", args...)
   453		cmd.Dir = dir
   454		if out, err := cmd.CombinedOutput(); err != nil {
   455			t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
   456		}
   457	}
   458	
   459	// gitHardenHookRepo builds a repository carrying a live post-index-change hook
   460	// and returns the file that hook appends a line to on every execution.
   461	//
   462	// The hook is written straight to disk because git has no command that installs
   463	// one, and it writes only to that file: post-index-change inherits the caller's
   464	// stdout, so a chattier payload would corrupt the porcelain under test rather
   465	// than merely proving it ran.
   466	//
   467	// b.txt is the file the arming works on. gitHardenRepo leaves a.txt genuinely
   468	// modified, and git does not refresh the cached stat of a file whose content no
   469	// longer matches the index -- it has real work to report instead. The trigger
   470	// has to be a file that is still clean.
   471	func gitHardenHookRepo(t *testing.T) (repo, log string) {
   472		t.Helper()
   473		repo = gitHardenRepo(t)
   474		log = filepath.Join(t.TempDir(), "EXECUTIONS")
   475	
   476		hooks := filepath.Join(repo, ".git", "hooks")
   477		if err := os.MkdirAll(hooks, 0o755); err != nil {
   478			t.Fatal(err)
   479		}
   480		body := "#!/bin/sh\necho fired >> " + log + "\nexit 0\n"
   481		if err := os.WriteFile(filepath.Join(hooks, gitHardenHookName), []byte(body), 0o755); err != nil {
   482			t.Fatal(err)
   483		}
   484	
   485		if err := os.WriteFile(filepath.Join(repo, "b.txt"), []byte("clean\n"), 0o644); err != nil {
   486			t.Fatal(err)
   487		}
   488		// Staging b.txt alone keeps a.txt in the index exactly as HEAD has it, so
   489		// the commit does not swallow the worktree modification the other tests in
   490		// this file depend on.
   491		gitHardenRun(t, repo, "add", "b.txt")
   492		gitHardenRun(t, repo, "commit", "-qm", "armed")
   493		return repo, log
   494	}
   495	
   496	// gitHardenArmHook leaves b.txt's content alone and makes only its stat data
   497	// disagree with the index, which is the state that costs git an index rewrite.
   498	// The timestamp is pushed into the future because git additionally refuses to
   499	// trust a cached stat whose mtime is not safely in the past, so a future date
   500	// arms the check on any filesystem timestamp granularity.
   501	func gitHardenArmHook(t *testing.T, repo, log string) {
   502		t.Helper()
   503		future := time.Now().Add(365 * 24 * time.Hour)
   504		if err := os.Chtimes(filepath.Join(repo, "b.txt"), future, future); err != nil {
   505			t.Fatal(err)
   506		}
   507		if err := os.Remove(log); err != nil && !os.IsNotExist(err) {
   508			t.Fatal(err)
   509		}
   510	}
   511	
   512	// gitHardenHookExecutions counts the lines the payload appended, so a failure
   513	// can say how many times the repository ran code rather than just that it did.
   514	func gitHardenHookExecutions(t *testing.T, log string) int {
   515		t.Helper()
   516		data, err := os.ReadFile(log)
   517		if os.IsNotExist(err) {
   518			return 0
   519		}
   520		if err != nil {
   521			t.Fatalf("read hook log: %v", err)
   522		}
   523		return len(strings.Fields(string(data)))
   524	}
   525	
   526	// gitHardenRequireLiveHook proves the arming fires before anything is asserted
   527	// about it. Without this control a hook test that silently stopped arming
   528	// anything -- a git change, a coarse-grained filesystem -- would keep passing
   529	// while defending nothing.
   530	func gitHardenRequireLiveHook(t *testing.T, repo, log string) {
   531		t.Helper()
   532		gitHardenArmHook(t, repo, log)
   533		gitHardenRunWithHooks(t, repo, "status", "--porcelain")
   534		if gitHardenHookExecutions(t, log) == 0 {
   535			t.Skipf("plain `git status` did not run %s here, so the vector cannot be exercised", gitHardenHookName)
   536		}
   537	}
   538	
   539	// gitHardenBrainEnv points the real commands at a throwaway brain store. The
   540	// commands below are driven through NewRootCommand rather than through the
   541	// individual git helpers because the finding is about what a user typing
   542	// `entire-brain status` gets, and because the command layer is where a future
   543	// git spawn that forgot the runner would show up.
   544	func gitHardenBrainEnv(t *testing.T, repo string) EntireEnv {
   545		t.Helper()
   546		root := t.TempDir()
   547		return EntireEnv{
   548			RepoRoot:        repo,
   549			PluginDataDir:   filepath.Join(root, "data"),
   550			PluginCacheDir:  filepath.Join(root, "cache"),
   551			PluginStateDir:  filepath.Join(root, "state"),
   552			PluginConfigDir: filepath.Join(root, "config"),
   553		}
   554	}
   555	
   556	// gitHardenAssertCommandsRunNoHook drives every command the vector was measured
   557	// on and asserts the repository never got to run code. A command that fails is
   558	// still evidence -- the hook must not run either way -- so its error is
   559	// reported alongside a violation rather than ending the test early.
   560	func gitHardenAssertCommandsRunNoHook(t *testing.T, repo, log, vector string) {
   561		t.Helper()
   562		env := gitHardenBrainEnv(t, repo)
   563		for _, argv := range [][]string{
   564			{"refresh", "--worktree", "--agent", "none"},
   565			{"refresh", "--agent", "none"},
   566			{"status"},
   567			{"status", "--verbose"},
   568			{"overview"},
   569		} {
   570			gitHardenArmHook(t, repo, log)
   571			cmd := NewRootCommand(Options{Version: "test-version", Env: env})
   572			var out bytes.Buffer
   573			cmd.SetOut(&out)
   574			cmd.SetErr(&out)
   575			cmd.SetArgs(argv)
   576			err := cmd.Execute()
   577			if n := gitHardenHookExecutions(t, log); n != 0 {
   578				t.Fatalf("SECURITY: `entire-brain %s` ran a repo-local %s hook %d time(s) via %s (command err: %v)\n%s",
   579					strings.Join(argv, " "), gitHardenHookName, n, vector, err, out.String())
   580			}
   581		}
   582	}
   583	
   584	// TestIndexingDoesNotRunRepoLocalGitHooks is the cheapest arming of all: a file
   585	// and a chmod, with nothing at all written to .git/config.
   586	func TestIndexingDoesNotRunRepoLocalGitHooks(t *testing.T) {
   587		gitHardenSkipUnsupported(t)
   588		repo, log := gitHardenHookRepo(t)
   589		gitHardenRequireLiveHook(t, repo, log)
   590	
   591		gitHardenAssertCommandsRunNoHook(t, repo, log, ".git/hooks")
   592	
   593		// The same vector at the two functions every one of those commands reaches
   594		// it through, so a regression is reported against the code that carries the
   595		// defect and not only against the command that surfaced it.
   596		gitHardenArmHook(t, repo, log)
   597		if _, err := gitStatusPorcelainAll(context.Background(), ExecRunner{}, repo); err != nil {
   598			t.Fatalf("gitStatusPorcelainAll: %v", err)
   599		}
   600		if n := gitHardenHookExecutions(t, log); n != 0 {
   601			t.Fatalf("SECURITY: gitStatusPorcelainAll ran a repo-local %s hook %d time(s)", gitHardenHookName, n)
   602		}
   603	
   604		gitHardenArmHook(t, repo, log)
   605		fingerprint, err := worktreeFingerprint(context.Background(), ExecRunner{}, repo)
   606		if err != nil {
   607			t.Fatalf("worktreeFingerprint: %v", err)
   608		}
   609		if n := gitHardenHookExecutions(t, log); n != 0 {
   610			t.Fatalf("SECURITY: worktreeFingerprint ran a repo-local %s hook %d time(s)", gitHardenHookName, n)
   611		}
   612		// Suppressing hooks must not cost the read: git still has to refresh the
   613		// index and report the worktree, it just must not announce it to the
   614		// repository's own code.
   615		if fingerprint == "" {
   616			t.Fatal("empty fingerprint")
   617		}
   618	}
   619	
   620	// TestIndexingDoesNotRunGitHooksRelocatedByHooksPath covers the config-key
   621	// half. core.hooksPath moves the directory, so a neutralizer that only ignored
   622	// .git/hooks -- or that pointed core.hooksPath at a RELATIVE path, which git
   623	// resolves against the repository's own worktree -- would still execute here.
   624	func TestIndexingDoesNotRunGitHooksRelocatedByHooksPath(t *testing.T) {
   625		gitHardenSkipUnsupported(t)
   626		repo, log := gitHardenHookRepo(t)
   627	
   628		elsewhere := filepath.Join(t.TempDir(), "hooks")
   629		if err := os.MkdirAll(elsewhere, 0o755); err != nil {
   630			t.Fatal(err)
   631		}
   632		body, err := os.ReadFile(filepath.Join(repo, ".git", "hooks", gitHardenHookName))
   633		if err != nil {
   634			t.Fatal(err)
   635		}
   636		if err := os.WriteFile(filepath.Join(elsewhere, gitHardenHookName), body, 0o755); err != nil {
   637			t.Fatal(err)
   638		}
   639		// Remove the original so a pass cannot come from the default directory
   640		// being the one that was neutralized.
   641		if err := os.Remove(filepath.Join(repo, ".git", "hooks", gitHardenHookName)); err != nil {
   642			t.Fatal(err)
   643		}
   644		gitHardenRun(t, repo, "config", "core.hooksPath", elsewhere)
   645	
   646		gitHardenRequireLiveHook(t, repo, log)
   647		gitHardenAssertCommandsRunNoHook(t, repo, log, "core.hooksPath")
   648	}

