  3	import (
  4		"regexp"
  5		"strings"
  6		"testing"
  7	
  8		"github.com/spf13/cobra"
  9	)
 10	
 11	// `guide` is the command set an agent is told to work from — it is the FIRST
 12	// thing a coding agent reads about this tool, and every line in it is a promise
 13	// that the line can be typed. Nothing checked that. The guide is a hand-written
 14	// string literal, so a renamed flag or a subcommand moved under a different
 15	// parent silently turns it into instructions for a tool that no longer exists,
 16	// and an agent that follows it gets "unknown command" instead of an answer.
 17	//
 18	// This does not pin the guide's wording. It extracts every `entire brain …`
 19	// invocation the guide prints, resolves the verbs against the real command tree
 20	// and every long flag against that command's real flag set. Rewrite the guide
 21	// however you like; you may not advertise something that is not there.
 22	
 23	// guideInvocation matches an indented command line in the guide body.
 24	var guideInvocation = regexp.MustCompile(`(?m)^\s+entire brain ([^\n#]+)`)
 25	
 26	// guideCommandLines returns the guide's invocations, each already split into
 27	// tokens with the trailing comment removed.
 28	func guideCommandLines(t *testing.T) [][]string {
 29		t.Helper()
 30		t.Chdir(t.TempDir()) // Standalone reference; never inspect real plugin state.
 31		out, err := execute(t, NewRootCommand(Options{Version: "test"}), "agent-guide")
 32		if err != nil {
 33			t.Fatalf("guide: %v", err)
 34		}
 35		var lines [][]string
 36		for _, match := range guideInvocation.FindAllStringSubmatch(out, -1) {
 37			if fields := strings.Fields(match[1]); len(fields) > 0 {
 38				lines = append(lines, fields)
 39			}
 40		}
 41		if len(lines) < 20 {
 42			t.Fatalf("only %d invocations found in the guide — the extraction is broken, not the guide", len(lines))
 43		}
 44		return lines
 45	}
 46	
 47	// guidePlaceholder reports whether a token is a documentation placeholder
 48	// (`<query>`, `[repo]`, `"<task>"`, `<id>...`) rather than a real operand.
 49	func guidePlaceholder(token string) bool {
 50		trimmed := strings.Trim(token, `"'`)
 51		return strings.HasPrefix(trimmed, "<") || strings.HasPrefix(trimmed, "[")
 52	}
 53	
 54	// guideResolvePath walks a guide invocation's leading tokens against the real
 55	// command tree and returns the command it names, plus the tokens consumed. A
 56	// token is only treated as a subcommand while the command reached so far HAS
 57	// subcommands; once a leaf is reached the rest are operands
 58	// (`inspect graph-ui semantic-graph.html`), not a misspelled verb. That
 59	// distinction is the whole point: an operand must be ignored, a verb that does
 60	// not exist must fail.
 61	func guideResolvePath(t *testing.T, root *cobra.Command, tokens []string) (*cobra.Command, bool) {
 62		t.Helper()
 63		cmd := root
 64		consumed := 0
 65		for _, token := range tokens {
 66			if strings.HasPrefix(token, "-") || guidePlaceholder(token) {
 67				break
 68			}
 69			if consumed > 0 && !cmd.HasSubCommands() {
 70				break // a leaf command: everything left is an operand
 71			}
 72			next := guideSubcommand(cmd, token)
 73			if next == nil {
 74				t.Errorf("guide advertises `entire brain %s`, but %q is not a command under %q",
 75					strings.Join(tokens, " "), token, cmd.CommandPath())
 76				return nil, false
 77			}
 78			cmd, consumed = next, consumed+1
 79		}
 80		if consumed == 0 {
 81			t.Errorf("guide line %q names no command", strings.Join(tokens, " "))
 82			return nil, false
 83		}
 84		return cmd, true
 85	}
 86	
 87	// guideSubcommand finds a direct subcommand by name or alias.
 88	func guideSubcommand(parent *cobra.Command, name string) *cobra.Command {
 89		for _, sub := range parent.Commands() {
 90			if sub.Name() == name {
 91				return sub
 92			}
 93			for _, alias := range sub.Aliases {
 94				if alias == name {
 95					return sub
 96				}
 97			}
 98		}
 99		return nil
100	}
101	
102	func TestGuideOnlyAdvertisesCommandsThatExist(t *testing.T) {
103		root := NewRootCommand(Options{Version: "test"})
104		for _, tokens := range guideCommandLines(t) {
105			guideResolvePath(t, root, tokens)
106		}
107	}
108	
109	func TestGuideOnlyAdvertisesFlagsThatExist(t *testing.T) {
110		root := NewRootCommand(Options{Version: "test"})
111		checked := 0
112		for _, tokens := range guideCommandLines(t) {
113			cmd, ok := guideResolvePath(t, root, tokens)
114			if !ok {
115				continue // the command test above already reports this
116			}
117			for _, token := range tokens {
118				// `[--scope local|cross-cutting]` and `--path category.sub.type`
119				// both appear; strip the documentation brackets and any value.
120				name := strings.TrimLeft(token, "[")
121				name = strings.TrimRight(name, "],")
122				if !strings.HasPrefix(name, "--") {
123					continue
124				}
125				name = strings.SplitN(strings.TrimPrefix(name, "--"), "=", 2)[0]
126				if name == "" {
127					continue
128				}
129				checked++
130				if lookupGuideFlag(cmd, name) == nil {
131					t.Errorf("guide advertises --%s on `%s`, which has no such flag", name, cmd.CommandPath())
132				}
133			}
134		}
135		if checked == 0 {
136			t.Fatal("no flags extracted from the guide — the test is checking nothing")
137		}
138	}
139	
140	// lookupGuideFlag resolves a long flag on a command or any of its parents
141	// (persistent flags are inherited).
142	func lookupGuideFlag(cmd *cobra.Command, name string) any {
143		if f := cmd.Flags().Lookup(name); f != nil {
144			return f
145		}
146		for parent := cmd.Parent(); parent != nil; parent = parent.Parent() {
147			if f := parent.PersistentFlags().Lookup(name); f != nil {
148				return f
149			}
150		}
151		return nil
152	}
153	
154	// TestGuideRetrievalFlagClaimIsTrue pins the guide's one prose claim about
155	// flags — "search/vsearch/query take --json/--format json|cli/--limit/-n/
156	// --branch, get/multi-get take --json/--format json|cli/--branch" — to the
157	// commands themselves. Prose is where an advertised flag hides from a
158	// line-by-line extractor.
159	func TestGuideRetrievalFlagClaimIsTrue(t *testing.T) {
160		root := NewRootCommand(Options{Version: "test"})
161		for _, tc := range []struct {
162			verb  string
163			flags []string
164		}{
165			{"search", []string{"json", "format", "limit", "branch"}},
166			{"vsearch", []string{"json", "format", "limit", "branch"}},
167			{"query", []string{"json", "format", "limit", "branch"}},
168			{"get", []string{"json", "format", "branch"}},
169			{"multi-get", []string{"json", "format", "branch"}},
170		} {
171			cmd, _, err := root.Find([]string{tc.verb})
172			if err != nil || cmd == root {
173				t.Errorf("guide names `entire brain %s`, which does not resolve", tc.verb)
174				continue
175			}
176			for _, name := range tc.flags {
177				if lookupGuideFlag(cmd, name) == nil {
178					t.Errorf("guide claims `%s` takes --%s; it does not", tc.verb, name)
179				}
180			}
181		}
182		// The guide also claims the short -n spelling for the three search verbs.
183		for _, verb := range []string{"search", "vsearch", "query"} {
184			cmd, _, err := root.Find([]string{verb})
185			if err != nil {
186				continue
187			}
188			if cmd.Flags().ShorthandLookup("n") == nil {
189				t.Errorf("guide claims `%s` takes -n; it does not", verb)
190			}
191		}
192	}

