 3	import (
 4		"encoding/json"
 5		"strings"
 6		"testing"
 7		"time"
 8	)
 9	
10	func TestBuildHandoffPacket(t *testing.T) {
11		_, manifest, index := historyEvalFixture(t) // s1 (older) + s2, with request/decision/validation records
12		now := time.Date(2026, 6, 10, 13, 0, 0, 0, time.UTC)
13		facts := []factRecord{
14			{ID: "f:old", Kind: factKindConvention, Text: "older fact", Status: factStatusActive, UpdatedAt: now.Add(-3 * time.Hour)},
15			{ID: "f:new", Kind: factKindClosedNegative, Text: "newer dead end", Status: factStatusActive, UpdatedAt: now.Add(-time.Hour)},
16			{ID: "f:gone", Kind: factKindDecision, Text: "superseded", Status: factStatusSuperseded, UpdatedAt: now},
17		}
18		// Fixture sessions are created at 10:00 (s1) and 11:00 (s2) on the
19		// fixture's own clock; a distill at 10:30 leaves exactly s2 undigested.
20		manifest.Sources.Facts = &factSourceManifest{GeneratedAt: time.Date(2026, 6, 10, 10, 30, 0, 0, time.UTC)}
21	
22		p := buildHandoffPacket(manifest, index, facts, "main", 5, now, sessionReadGuard{})
23	
24		if len(p.Sessions) != 2 {
25			t.Fatalf("expected both sessions, got %d", len(p.Sessions))
26		}
27		// Most recent session first; its records attributed via transcript path.
28		s2 := p.Sessions[0]
29		if s2.SessionID != shortSessionID("session-bbbb-2222") {
30			t.Fatalf("sessions must be recency-ordered, got %s first", s2.SessionID)
31		}
32		if len(s2.Decisions) != 1 || !strings.Contains(s2.Decisions[0], "export cursor") {
33			t.Fatalf("s2's decision record missing: %+v", s2)
34		}
35		if len(s2.Validations) != 1 || !strings.Contains(s2.Validations[0], "cache hit rate") {
36			t.Fatalf("s2's validation record missing: %+v", s2)
37		}
38		s1 := p.Sessions[1]
39		if s1.Request != "add retry backoff to the fetcher" {
40			t.Fatalf("s1's opening request (lowest-line request record) missing: %q", s1.Request)
41		}
42	
43		// Recent facts: active only, newest first.
44		if len(p.RecentFacts) != 2 || p.RecentFacts[0].ID != "f:new" {
45			t.Fatalf("recent facts should be active-only, newest first: %+v", p.RecentFacts)
46		}
47		// Both fixture sessions predate... s2 created now-1h, distill at now-90m →
48		// s2 (and only s2) is newer than the last distill.
49		if p.SessionsSinceDistill != 1 {
50			t.Fatalf("expected 1 session since distill, got %d", p.SessionsSinceDistill)
51		}
52		if len(p.Branches) != 1 || p.Branches[0] != "main" {
53			t.Fatalf("active branches = %v, want [main]", p.Branches)
54		}
55	}
56	
57	func TestBuildHandoffPacketOmitsExcludedSessionCanary(t *testing.T) {
58		_, manifest, index := historyEvalFixture(t)
59		const canary = "PRIVATE-HANDOFF-CANARY"
60		excluded := manifest.Sources.Sessions.Sessions[1]
61		for i := range index.Records {
62			if index.Records[i].Path == excluded.TranscriptPath {
63				index.Records[i].Summary += " " + canary
64			}
65		}
66		facts := []factRecord{{
67			ID: "fact:private", Status: factStatusActive, Text: canary,
68			Provenance: []factAnchor{{SessionID: excluded.SessionID, Transcript: excluded.TranscriptPath}},
69		}}
70		stones := sessionTombstones{Version: sessionTombstonesVersion, Excluded: map[string]sessionTombstone{
71			excluded.SessionID: {At: time.Now().UTC()},
72		}}
73		guard := sessionReadGuard{ids: stones.Excluded, paths: excludedTranscriptPaths(manifest, stones)}
74		packet := buildHandoffPacket(manifest, index, facts, "main", 5, time.Now().UTC(), guard)
75		data, err := json.Marshal(packet)
76		if err != nil {
77			t.Fatal(err)
78		}
79		if strings.Contains(string(data), canary) || strings.Contains(string(data), excluded.SessionID) {
80			t.Fatalf("handoff exposed excluded session: %s", data)
81		}
82		if len(packet.Sessions) != len(manifest.Sources.Sessions.Sessions)-1 || len(packet.RecentFacts) != 0 {
83			t.Fatalf("handoff did not filter excluded session/facts: %+v", packet)
84		}
85	}
86	
87	func TestBriefRequiresTaskUnlessHandoff(t *testing.T) {
88		opts := Options{Env: EntireEnv{RepoRoot: t.TempDir()}, Runner: ExecRunner{}, Now: time.Now}
89		if _, err := execute(t, newBrainBriefCommand(opts)); err == nil || !strings.Contains(err.Error(), "--handoff") {
90			t.Fatalf("brief without a task should point at --handoff, got %v", err)
91		}
92	}

