183	// TestHistoryScanCacheV6AnnotatedEntriesIgnored ensures old entries whose
184	// Branch may already contain manifest inference cannot masquerade as v7 raw
185	// scanner records.
186	func TestHistoryScanCacheV6AnnotatedEntriesIgnored(t *testing.T) {
187		// Later versions exist because independent formats were developed in
188		// parallel and are invalidated rather than guessed apart; a v6 entry must
189		// likewise never be read as a current-format one, whatever the current
190		// version is.
191		if historyScanCacheVersion < 7 {
192			t.Fatalf("test guards the incompatible v6 -> v7 cache migration; any later version must also reject v6 entries (version = %d)", historyScanCacheVersion)
193		}
194		dir := t.TempDir()
195		if err := os.MkdirAll(filepath.Join(dir, historyDirName), 0o700); err != nil {
196			t.Fatalf("mkdir: %v", err)
197		}
198		stale := historyScanCache{Version: 6, Files: map[string]historyScanCacheEntry{
199			"sessions/main/old.jsonl": {Records: []historyRecord{{ID: "stale", Branch: "main"}}},
200		}}
201		var buf bytes.Buffer
202		gz := gzip.NewWriter(&buf)
203		if err := json.NewEncoder(gz).Encode(stale); err != nil {
204			t.Fatalf("encode: %v", err)
205		}
206		if err := gz.Close(); err != nil {
207			t.Fatalf("close gzip: %v", err)
208		}
209		if err := os.WriteFile(filepath.Join(dir, filepath.FromSlash(historyScanCachePath)), buf.Bytes(), 0o600); err != nil {
210			t.Fatalf("write cache: %v", err)
211		}
212		loaded := loadHistoryScanCache(dir)
213		if len(loaded.Files) != 0 {
214			t.Fatalf("expected version mismatch to yield empty cache, got %+v", loaded.Files)
215		}
216	}

