   154	// TestGuideRetrievalFlagClaimIsTrue pins the guide's one prose claim about
   155	// flags — "search/vsearch/query take --json/--format json|cli/--limit/-n/
   156	// --branch, get/multi-get take --json/--format json|cli/--branch" — to the
   157	// commands themselves. Prose is where an advertised flag hides from a
   158	// line-by-line extractor.
   159	func TestGuideRetrievalFlagClaimIsTrue(t *testing.T) {
   160		root := NewRootCommand(Options{Version: "test"})
   161		for _, tc := range []struct {
   162			verb  string
   163			flags []string
