   176			for _, name := range tc.flags {
   177				if lookupGuideFlag(cmd, name) == nil {
   178					t.Errorf("guide claims `%s` takes --%s; it does not", tc.verb, name)
   179				}
   180			}
   181		}
   182		// The guide also claims the short -n spelling for the three search verbs.
   183		for _, verb := range []string{"search", "vsearch", "query"} {
   184			cmd, _, err := root.Find([]string{verb})
   185			if err != nil {
   186				continue
   187			}
   188			if cmd.Flags().ShorthandLookup("n") == nil {
   189				t.Errorf("guide claims `%s` takes -n; it does not", verb)
   190			}
   191		}
