   141		if err := os.WriteFile(path, []byte(newLine), 0o600); err != nil {
   142			t.Fatal(err)
   143		}
   144		if err := os.Chtimes(path, oldInfo.ModTime(), oldInfo.ModTime()); err != nil {
   145			t.Fatal(err)
   146		}
   147		newInfo, err := os.Stat(path)
   148		if err != nil {
   149			t.Fatal(err)
   150		}
   151		if newInfo.Size() != oldInfo.Size() || !newInfo.ModTime().Equal(oldInfo.ModTime()) {
   152			t.Fatal("replacement did not preserve cache-visible metadata")
   153		}
   154		index, _, err := buildBrainHistoryIndex(brainDir, time.Now().UTC(), nil)
   155		if err != nil {
   156			t.Fatal(err)
   157		}
   158		joined := ""
   159		for _, record := range index.Records {
   160			joined += record.Summary + "\n"
   161		}
   162		if strings.Contains(joined, "old searchable token") || !strings.Contains(joined, "new searchable token") {
   163			t.Fatalf("same-metadata replacement reused stale cache records: %q", joined)
   164		}
   165		cache := loadHistoryScanCache(brainDir)
   166		entry := cache.Files[rel]
   167		if entry.ContentDigest == "" {
   168			t.Fatal("v7 cache entry omitted its content digest")
   169		}
