 95	// TestHistoryIndexRejectsMutationBetweenFingerprintAndScan locks the
 96	// fail-closed ingestion contract: a transcript rewritten between identity
 97	// capture and the scan aborts the build. It used to be recorded as a warning
 98	// and the index published anyway, but a partial or mixed-generation inventory
 99	// must never be published as a complete projection.
100	func TestHistoryIndexRejectsMutationBetweenFingerprintAndScan(t *testing.T) {
101		brainDir, targetPath, info, now := historyMutationRaceFixture(t)
102		after := "{\"type\":\"agent_message\",\"message\":\"Decision: mutated after fingerprint.\"}\n"
103		mutated := false
104		_, _, err := buildBrainHistoryIndex(brainDir, now.Add(time.Second), func(done, total int) {
105			if done != 0 || mutated {
106				return
107			}
108			mutated = true
109			if err := os.WriteFile(targetPath, []byte(after), 0o600); err != nil {
110				t.Fatal(err)
111			}
112			if err := os.Chtimes(targetPath, info.ModTime(), info.ModTime()); err != nil {
113				t.Fatal(err)
114			}
115		})
116		if !mutated {
117			t.Fatal("progress hook did not mutate target after identity capture")
118		}
119		if err == nil {
120			t.Fatal("a transcript mutated mid-build must abort the index, not warn")
121		}
122		if !errors.Is(err, errHistorySessionInventoryDegraded) && !strings.Contains(err.Error(), memoryErrSourceStale) {
123			t.Fatalf("mutation error = %v, want a typed degraded/stale refusal", err)
124		}
125	}
