127	// TestHistoryCacheEmptyRejectsOpenAndIdentityRaces locks that a transcript
128	// deleted, inode-replaced, or symlink-swapped mid-build aborts the index and
129	// never lets external bytes in. #83 made these typed refusals rather than
130	// per-file warnings.
131	func TestHistoryCacheEmptyRejectsOpenAndIdentityRaces(t *testing.T) {
132		for _, mode := range []string{"deleted", "inode replacement", "symlink swap"} {
133			t.Run(mode, func(t *testing.T) {
134				brainDir := t.TempDir()
135				sessionDir := filepath.Join(brainDir, exportSessionsDirectory, "main")
136				if err := os.MkdirAll(sessionDir, 0o700); err != nil {
137					t.Fatal(err)
138				}
139				path := filepath.Join(sessionDir, "20260717T010000Z-session.jsonl")
140				if err := os.WriteFile(path, []byte(`{"type":"agent_message","message":"Decision: safe in-repo record."}`+"\n"), 0o600); err != nil {
141					t.Fatal(err)
142				}
143				externalPath := filepath.Join(t.TempDir(), "external.jsonl")
144				secret := "Decision: external secret must never be indexed."
145				if err := os.WriteFile(externalPath, []byte(`{"type":"agent_message","message":"`+secret+`"}`+"\n"), 0o600); err != nil {
146					t.Fatal(err)
147				}
148				if mode == "symlink swap" {
149					probe := filepath.Join(t.TempDir(), "probe")
150					if err := os.Symlink(externalPath, probe); err != nil {
151						t.Skipf("symlinks unavailable: %v", err)
152					}
153				}
154				mutated := false
155				index, _, err := buildBrainHistoryIndex(brainDir, time.Date(2026, 7, 18, 11, 0, 0, 0, time.UTC), func(done, total int) {
156					if done != 0 || mutated {
157						return
158					}
159					mutated = true
160					if err := os.Remove(path); err != nil {
161						t.Fatal(err)
162					}
163					switch mode {
164					case "inode replacement":
165						if err := os.Rename(externalPath, path); err != nil {
166							t.Fatal(err)
167						}
168					case "symlink swap":
169						if err := os.Symlink(externalPath, path); err != nil {
170							t.Fatal(err)
171						}
172					}
173				})
174				if err == nil {
175					t.Fatal("an open/identity race must abort the index, not warn")
176				}
177				if !errors.Is(err, errHistorySessionInventoryDegraded) {
178					t.Fatalf("race error = %v, want the typed degraded refusal", err)
179				}
180				if strings.Contains(err.Error(), secret) {
181					t.Fatalf("refusal exposed external content: %v", err)
182				}
183				if len(index.Records) != 0 {
184					t.Fatalf("external or unstable bytes entered the index: %+v", index.Records)
185				}
186				if cache := loadHistoryScanCache(brainDir); len(cache.Files) != 0 {
187					t.Fatalf("unstable file entered cache: %+v", cache.Files)
188				}
189			})
190		}
191	}
