204		for _, path := range []string{oldPath, newPath} {
205			if err := os.WriteFile(path, []byte("Decision: candidate.\n"), 0o600); err != nil {
206				t.Fatal(err)
207			}
208		}
209		_, _, err := buildBrainHistoryIndex(brainDir, time.Date(2026, 7, 18, 12, 0, 0, 0, time.UTC), func(done, total int) {
210			if done != 0 {
211				return
212			}
213			for _, path := range []string{oldPath, newPath} {
