216				}
217			}
218		})
219		if err == nil {
220			t.Fatal("removed transcripts must abort the index")
221		}
222		// Newest-first scan order: the newer transcript is the one reported.
223		if !strings.Contains(err.Error(), filepath.Base(newPath)) {
224			t.Fatalf("refusal = %v, want the newest-first candidate %q", err, filepath.Base(newPath))
225		}
