259	func TestHistoryCacheEmptyFingerprintsButDoesNotCacheParseLimitFailure(t *testing.T) {
260		brainDir := t.TempDir()
261		path := filepath.Join(brainDir, exportSessionsDirectory, "main", "20260717T010000Z-oversized.txt")
262		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
