272			progress = append(progress, [2]int{done, total})
273		})
274		if err != nil {
275			t.Fatal(err)
276		}
277		if want := [][2]int{{0, 1}, {1, 1}}; !reflect.DeepEqual(progress, want) {
278			t.Fatalf("progress = %v, want %v", progress, want)
279		}
