282		// which one had gone missing.
283		if want := []string{"history records skipped for sessions/main/20260717T010000Z-oversized.txt: bufio.Scanner: token too long"}; !reflect.DeepEqual(source.Warnings, want) {
284			t.Fatalf("warnings = %v, want %v", source.Warnings, want)
285		}
286		const wantFingerprint = "sha256:999bbc4efb10f491343b79dee94e03b966545c254838a9f00d681e3f3bc04aea"
287		if source.TranscriptsFingerprint != wantFingerprint {
288			t.Fatalf("fingerprint = %q, want %q", source.TranscriptsFingerprint, wantFingerprint)
289		}
