 34			DefaultBranch: "main",
 35			Sources: &brainSources{Sessions: &sessionSourceManifest{GeneratedAt: now, DefaultBranch: "main", Sessions: []exportSession{
 36				{SessionID: "session-aaaa-1111", Branch: "main", TranscriptPath: "sessions/main/s1.jsonl", CreatedAt: now.Add(-2 * time.Hour)},
 37				{SessionID: "session-bbbb-2222", Branch: "main", TranscriptPath: "sessions/main/s2.jsonl", CreatedAt: now.Add(-time.Hour)},
 38			}}},
 39		}
 40		index := historyIndex{GeneratedAt: now, Records: []historyRecord{
 41			{ID: "r1", Kind: "decision", Path: "sessions/main/s1.jsonl", Line: 3, Summary: "decided to use exponential backoff with jitter for fetch retries"},
 42			{ID: "r2", Kind: "learning", Path: "sessions/main/s1.jsonl", Line: 9, Summary: "the fetcher must cap retry attempts at five to bound latency"},
 43			{ID: "r3", Kind: "request", Path: "sessions/main/s1.jsonl", Line: 1, Summary: "add retry backoff to the fetcher"},
 44			{ID: "r4", Kind: "decision", Path: "sessions/main/s2.jsonl", Line: 4, Summary: "the export cursor reuses unchanged transcripts so refresh stays incremental"},
 45			{ID: "r5", Kind: "validation", Path: "sessions/main/s2.jsonl", Line: 8, Summary: "verified the exporter cache hit rate on the live brain"},
 46		}}
 47		return brainDir, manifest, index
 48	}
