 50	func TestGenerateHistoryEvalTasksLabelsByTranscript(t *testing.T) {
 51		brainDir, manifest, index := historyEvalFixture(t)
 52		tasks := generateHistoryEvalTasks(brainDir, manifest, index, "", 2, 0, 0, false)
 53		if len(tasks) != 2 {
 54			t.Fatalf("expected 2 tasks, got %d: %+v", len(tasks), tasks)
 55		}
 56		byTask := map[string]evalTask{}
 57		for _, task := range tasks {
 58			byTask[task.Task] = task
 59		}
 60		s1, ok := byTask["add retry backoff to the fetcher"]
 61		if !ok {
 62			t.Fatalf("s1's opening request not recovered as a task: %+v", tasks)
 63		}
 64		// r3 is kind=request: the general arm can never surface it, so labeling it
 65		// would cap recall at an unreachable target.
 66		if len(s1.Relevant) != 2 || s1.Relevant[0] != "r1" || s1.Relevant[1] != "r2" {
 67			t.Fatalf("s1 labels = %v, want [r1 r2] (request-kind excluded)", s1.Relevant)
 68		}
 69		if s1.QueryType != queryTypeHowto {
 70			t.Errorf("s1 query type = %q, want howto", s1.QueryType)
 71		}
 72	
 73		// min-records: raising the floor above s2's 2 rankable records drops it.
 74		tasks = generateHistoryEvalTasks(brainDir, manifest, index, "", 3, 0, 0, false)
 75		if len(tasks) != 0 {
 76			t.Fatalf("min-records=3 should disqualify both sessions, got %d", len(tasks))
 77		}
 78	}
