 80	// TestGenerateHistoryEvalTasksMidtaskStratum covers Phase 2 item 8: mid-session
 81	// follow-up questions become their own stratum, labeled with the records that
 82	// FOLLOW each question — the work the answer manifested in.
 83	func TestGenerateHistoryEvalTasksMidtaskStratum(t *testing.T) {
 84		brainDir, manifest, index := historyEvalFixture(t)
 85		index.Records = append(index.Records,
 86			// A follow-up question mid-way through s1, then more work after it.
 87			historyRecord{ID: "r6", Kind: "request", Path: "sessions/main/s1.jsonl", Line: 5, Summary: "why does the retry cap exist"},
 88			historyRecord{ID: "r7", Kind: "validation", Path: "sessions/main/s1.jsonl", Line: 12, Summary: "verified the cap bounds tail latency"},
 89			// A wrapper injection must never become a task.
 90			historyRecord{ID: "r8", Kind: "request", Path: "sessions/main/s1.jsonl", Line: 7, Summary: "<local-command-caveat>Caveat: local commands"},
 91		)
 92		tasks := generateHistoryEvalTasks(brainDir, manifest, index, "", 2, 0, 0, true)
 93	
 94		var mid []evalTask
 95		for _, task := range tasks {
 96			if task.QueryType == queryTypeMidtask {
 97				mid = append(mid, task)
 98			}
 99		}
100		if len(mid) != 1 {
101			t.Fatalf("expected exactly one midtask task (the wrapper filtered), got %d: %+v", len(mid), mid)
102		}
103		m := mid[0]
104		if m.Task != "why does the retry cap exist" {
105			t.Fatalf("midtask query = %q", m.Task)
106		}
107		// Labels: only s1 records AFTER line 5 — r2 (line 9) and r7 (line 12);
108		// r1 (line 3) precedes the question and must not be credited.
109		if len(m.Relevant) != 2 || m.Relevant[0] != "r2" || m.Relevant[1] != "r7" {
110			t.Fatalf("midtask labels = %v, want [r2 r7] (records after the question)", m.Relevant)
111		}
112		// The opening task keeps the full-session labels, now including r7.
113		for _, task := range tasks {
114			if task.Task == "add retry backoff to the fetcher" {
115				if len(task.Relevant) != 3 {
116					t.Fatalf("opening task labels = %v, want all 3 rankable records", task.Relevant)
117				}
118			}
119		}
120	}
121	
122	// TestHistoryEvalBM25SurfacesWhatSubstringMisses is the matches-null defect in
123	// miniature, as an eval measurement: a paraphrase query sharing one
124	// high-value term with the relevant record scores zero on the coverage-gated
125	// substring arm but is surfaced (and measured) by the BM25 arm.
126	func TestHistoryEvalBM25SurfacesWhatSubstringMisses(t *testing.T) {
127		brainDir := t.TempDir()
128		index := historyIndex{GeneratedAt: time.Now(), Records: []historyRecord{
129			{ID: "r1", Kind: "decision", Path: "sessions/main/s1.jsonl", Line: 1, Summary: "chose model2vec embeddings for the semantic recall backend"},
130			{ID: "r2", Kind: "decision", Path: "sessions/main/s1.jsonl", Line: 5, Summary: "progress output goes to stderr to keep json clean"},
131			{ID: "r3", Kind: "decision", Path: "sessions/main/s2.jsonl", Line: 2, Summary: "the watcher debounces filesystem events before refresh"},
132		}}
133		tasks := []evalTask{{ID: "t1", Task: "what did we pick for embeddings and what were the alternatives", Relevant: []string{"r1"}}}
134	
135		subArm, err := selectHistoryEvalArm("substring", brainDir, index, historyFTSRelevanceCutoff)
136		if err != nil {
137			t.Fatal(err)
138		}
139		subRes, err := runHistoryEval(tasks, 5, subArm)
140		if err != nil {
141			t.Fatal(err)
142		}
143		bmArm, err := selectHistoryEvalArm("bm25", brainDir, index, historyFTSRelevanceCutoff)
144		if err != nil {
145			t.Fatal(err)
146		}
147		bmRes, err := runHistoryEval(tasks, 5, bmArm)
148		if err != nil {
149			t.Fatal(err)
150		}
151		if bmRes[0].RelevantSurfaced != 1 || bmRes[0].Recall != 1 {
152			t.Fatalf("bm25 arm should surface r1: %+v", bmRes[0])
153		}
154		if subRes[0].RelevantSurfaced >= bmRes[0].RelevantSurfaced {
155			t.Fatalf("expected the coverage-gated substring arm to miss what bm25 finds (the defect being measured); substring=%d bm25=%d",
156				subRes[0].RelevantSurfaced, bmRes[0].RelevantSurfaced)
157		}
158		if bmRes[0].Tokens <= 0 || bmRes[0].UsefulPer1k <= 0 {
159			t.Fatalf("metrics not computed: %+v", bmRes[0])
160		}
161	}
162	
163	// TestHistoryEvalCutoffSweep proves --cutoff is a real lever: the weak
164	// one-term tail survives cutoff 0 and is trimmed at a high cutoff.
165	func TestHistoryEvalCutoffSweep(t *testing.T) {
166		brainDir := t.TempDir()
167		index := historyIndex{GeneratedAt: time.Now(), Records: []historyRecord{
168			{ID: "strong", Kind: "decision", Path: "p1", Line: 1, Summary: "embedding cache invalidation uses the model fingerprint"},
169			{ID: "weak", Kind: "decision", Path: "p2", Line: 1, Summary: "the cache directory is created lazily"},
170		}}
171		query := "embedding cache invalidation fingerprint"
172		loose, ok := rankHistoryViaFTSCutoff(brainDir, index, "history", query, 10, 0)
173		if !ok || len(loose) != 2 {
174			t.Fatalf("cutoff 0 should keep the weak one-term tail, got %d (ok=%v)", len(loose), ok)
175		}
176		tight, ok := rankHistoryViaFTSCutoff(brainDir, index, "history", query, 10, 0.99)
177		if !ok || len(tight) != 1 || tight[0].Record.ID != "strong" {
178			t.Fatalf("cutoff 0.99 should trim to the top match, got %+v (ok=%v)", tight, ok)
179		}
180	}
181	
182	// fixedEmbedder is a deterministic stub: texts map to fixed vectors, unknown
183	// text to the zero vector. The optional query prefix mirrors queryEmbedder.
184	type fixedEmbedder struct {
185		vecs map[string][]float32
186		dim  int
187	}
188	
189	func (f *fixedEmbedder) Embed(text string) []float32 {
190		if v, ok := f.vecs[text]; ok {
191			return v
192		}
193		return make([]float32, f.dim)
194	}
195	func (f *fixedEmbedder) Dim() int   { return f.dim }
196	func (f *fixedEmbedder) ID() string { return "fixed-test" }
197	
198	// TestHistoryFusedReachesTermDisjoint: the reachability claim for the
199	// prospective fused arm — a record sharing no term with the query is
200	// unreachable by BM25 but surfaces through the semantic side of the fusion.
201	func TestHistoryFusedReachesTermDisjoint(t *testing.T) {
202		brainDir := t.TempDir()
203		index := historyIndex{GeneratedAt: time.Now(), Records: []historyRecord{
204			{ID: "target", Kind: "decision", Path: "p1", Line: 1, Summary: "indentation uses spaces, never tabs"},
205			{ID: "noise1", Kind: "decision", Path: "p2", Line: 1, Summary: "release artifacts publish nightly"},
206			{ID: "noise2", Kind: "decision", Path: "p3", Line: 1, Summary: "reviews need two approvals"},
207		}}
208		query := "whitespace convention"
209		e := &fixedEmbedder{dim: 3, vecs: map[string][]float32{
210			query:                                 {1, 0, 0},
211			"indentation uses spaces, never tabs": {0.95, 0.05, 0},
212			"release artifacts publish nightly":   {0, 1, 0},
213			"reviews need two approvals":          {0, 0, 1},
214		}}
215	
216		// BM25 alone cannot reach the term-disjoint record.
217		if scored, ok := rankHistoryViaFTSCutoff(brainDir, index, "history", query, 5, historyFTSRelevanceCutoff); ok {
218			for _, s := range scored {
219				if s.Record.ID == "target" {
220					t.Fatalf("test premise broken: bm25 reached the term-disjoint record")
221				}
222			}
223		}
224		got, err := newHistoryFusedRanker(brainDir, index, e, historyFTSRelevanceCutoff).rank(query, 1)
225		if err != nil {
226			t.Fatal(err)
227		}
228		if len(got) != 1 || got[0].ID != "target" {
229			t.Fatalf("fused arm should surface the term-disjoint record first, got %+v", got)
230		}
231	}
232	
233	// TestHistoryEvalGenLoadCompareSeam covers the seam that broke when label
234	// discipline landed in facts_eval without touching this file: generated tasks
235	// must survive the write -> loadEvalTasks round trip, legacy files without
236	// label_source must still load (defaulted to provenance_silver), and two
237	// history-eval summaries must compare without --allow-proxy-comparison while
238	// staying non-proof (EvidenceBasis proxy).
239	func TestHistoryEvalGenLoadCompareSeam(t *testing.T) {
240		brainDir, manifest, index := historyEvalFixture(t)
241		tasks := generateHistoryEvalTasks(brainDir, manifest, index, "", 2, 0, 0, false)
242		if len(tasks) == 0 {
243			t.Fatal("fixture produced no tasks")
244		}
245		for _, task := range tasks {
246			if task.LabelSource != evalLabelSourceProvenanceSilver {
247				t.Fatalf("generated task %s label_source = %q, want provenance_silver", task.ID, task.LabelSource)
248			}
249		}
250	
251		// Round trip through the file format and the loader's validation.
252		data, err := json.Marshal(tasks)
253		if err != nil {
254			t.Fatal(err)
255		}
256		path := filepath.Join(t.TempDir(), "tasks.json")
257		if err := os.WriteFile(path, data, 0o600); err != nil {
258			t.Fatal(err)
259		}
260		loaded, err := loadEvalTasks(path)
261		if err != nil {
262			t.Fatalf("generated tasks must load: %v", err)
263		}
264	
265		// A legacy file (labels, no label_source) must load with the conservative
266		// silver default rather than being rejected.
267		for i := range tasks {
268			tasks[i].LabelSource = ""
269		}
270		legacy, err := json.Marshal(tasks)
271		if err != nil {
272			t.Fatal(err)
273		}
274		legacyPath := filepath.Join(t.TempDir(), "legacy.json")
275		if err := os.WriteFile(legacyPath, legacy, 0o600); err != nil {
276			t.Fatal(err)
277		}
278		legacyLoaded, err := loadEvalTasks(legacyPath)
279		if err != nil {
280			t.Fatalf("legacy task files must load: %v", err)
281		}
282		if legacyLoaded[0].LabelSource != evalLabelSourceProvenanceSilver {
283			t.Fatalf("legacy labels should default to provenance_silver, got %q", legacyLoaded[0].LabelSource)
284		}
285	
286		// Two same-truth history runs compare by default; basis stays non-proof.
287		arm, err := selectHistoryEvalArm("substring", brainDir, index, historyFTSRelevanceCutoff)
288		if err != nil {
289			t.Fatal(err)
290		}
291		results, err := runHistoryEval(loaded, 5, arm)
292		if err != nil {
293			t.Fatal(err)
294		}
295		for _, r := range results {
296			if r.Labeled && (r.RelevanceSource != evalRelevanceExplicitLabel || r.LabelSource != evalLabelSourceProvenanceSilver) {
297				t.Fatalf("history result %s must declare silver explicit labels, got source=%q label=%q", r.ID, r.RelevanceSource, r.LabelSource)
298			}
299		}
300		a, b := summarizeEval(results), summarizeEval(results)
301		comparisons, _, err := compareEvalSummariesWithOptions(a, b, 0.05, false)
302		if err != nil {
303			t.Fatalf("same-truth silver summaries must compare without --allow-proxy-comparison: %v", err)
304		}
305		for _, c := range comparisons {
306			if c.Metric == "precision" && c.EvidenceBasis != evalMetricEvidenceProxyOrMixed {
307				t.Fatalf("silver comparison must not claim proof basis, got %q", c.EvidenceBasis)
308			}
309		}
310	}

