252		data, err := json.Marshal(tasks)
253		if err != nil {
254			t.Fatal(err)
255		}
256		path := filepath.Join(t.TempDir(), "tasks.json")
257		if err := os.WriteFile(path, data, 0o600); err != nil {
258			t.Fatal(err)
259		}
260		loaded, err := loadEvalTasks(path)
261		if err != nil {
262			t.Fatalf("generated tasks must load: %v", err)
263		}
264	
265		// A legacy file (labels, no label_source) must load with the conservative
266		// silver default rather than being rejected.
267		for i := range tasks {
268			tasks[i].LabelSource = ""
269		}
270		legacy, err := json.Marshal(tasks)
271		if err != nil {
272			t.Fatal(err)
273		}
274		legacyPath := filepath.Join(t.TempDir(), "legacy.json")
275		if err := os.WriteFile(legacyPath, legacy, 0o600); err != nil {
276			t.Fatal(err)
277		}
278		legacyLoaded, err := loadEvalTasks(legacyPath)
279		if err != nil {
280			t.Fatalf("legacy task files must load: %v", err)
281		}
282		if legacyLoaded[0].LabelSource != evalLabelSourceProvenanceSilver {
283			t.Fatalf("legacy labels should default to provenance_silver, got %q", legacyLoaded[0].LabelSource)
284		}
285	
286		// Two same-truth history runs compare by default; basis stays non-proof.
287		arm, err := selectHistoryEvalArm("substring", brainDir, index, historyFTSRelevanceCutoff)
288		if err != nil {
289			t.Fatal(err)
290		}
291		results, err := runHistoryEval(loaded, 5, arm)
292		if err != nil {
293			t.Fatal(err)
294		}
295		for _, r := range results {
296			if r.Labeled && (r.RelevanceSource != evalRelevanceExplicitLabel || r.LabelSource != evalLabelSourceProvenanceSilver) {
297				t.Fatalf("history result %s must declare silver explicit labels, got source=%q label=%q", r.ID, r.RelevanceSource, r.LabelSource)
298			}
299		}
300		a, b := summarizeEval(results), summarizeEval(results)
301		comparisons, _, err := compareEvalSummariesWithOptions(a, b, 0.05, false)
302		if err != nil {
303			t.Fatalf("same-truth silver summaries must compare without --allow-proxy-comparison: %v", err)
304		}
305		for _, c := range comparisons {
306			if c.Metric == "precision" && c.EvidenceBasis != evalMetricEvidenceProxyOrMixed {
307				t.Fatalf("silver comparison must not claim proof basis, got %q", c.EvidenceBasis)
308			}
309		}
310	}

