 9	func TestHistoryFactSignalMatchesValuesCommandsPrint(t *testing.T) {
10		cases := []struct {
11			name string
12			text string
13		}{
14			{
15				"flag default from --help",
16				"      --confidence float   Minimum agent confidence to auto-apply a merge/supersede; below this it is queued for review (default 0.75)",
17			},
18			{"go constant", "\tdefaultFactConfidenceThreshold = 0.75"},
19			{"go declaration", "func applyFactActions(active []factRecord) {"},
20			{"typed declaration", "type factAction struct {"},
21			{"python default", "def merge(threshold = 0.75):"},
22			{"quoted assignment", `mode = "queued"`},
23			{"boolean assignment", "historyIndex = true"},
24			{"short assign", "threshold := 0.75"},
25			{"file line anchor", "internal/cli/facts_merge.go:17: constant declared here"},
26		}
27		for _, tc := range cases {
28			t.Run(tc.name, func(t *testing.T) {
29				if !historyTextHasCodeFactSignal(tc.text) {
30					t.Fatalf("expected a durable fact signal in %q", tc.text)
31				}
32			})
33		}
34	}
35	
36	func TestHistoryFactSignalIgnoresRoutineChatter(t *testing.T) {
37		cases := []struct {
38			name string
39			text string
40		}{
41			{"plain prose", "Let me look at how the reconcile engine is wired together."},
42			{"directory listing", "total 48"},
43			{"progress line", "Scanning 200 checkpoints"},
44			{"bare path", "internal/cli/facts_merge.go"},
45		}
46		for _, tc := range cases {
47			t.Run(tc.name, func(t *testing.T) {
48				if historyTextHasCodeFactSignal(tc.text) {
49					t.Fatalf("did not expect a fact signal in %q", tc.text)
50				}
51			})
52		}
53	}
54	
55	// The pre-decode line filter runs on RAW transcript lines, where embedded
56	// quotes are JSON-escaped. A line whose only content is a code fact used to be
57	// dropped before the fragment extractor could see it, so tool output carrying
58	// a decided value never reached the index unless narrative keywords happened
59	// to share the line.
60	func TestPrefilterAdmitsRawCodeFactLines(t *testing.T) {
61		lines := []string{
62			`{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"defaultFactConfidenceThreshold = 0.75"}]}}`,
63			`{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"--confidence float   Minimum agent confidence to auto-apply a merge/supersede; below this it is queued for review (default 0.75)"}]}}`,
64			`{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"timeout = 30\nretries = 5\nmode = \"strict\""}]}}`,
65		}
66		for _, line := range lines {
67			if !historyLineMayContainIndexedContent(line) {
68				t.Errorf("raw code-fact line dropped before decode: %q", line)
69			}
70		}
71	}
72	
73	func TestPrefilterStillSkipsIrrelevantLines(t *testing.T) {
74		lines := []string{
75			`{"type":"system","subtype":"init"}`,
76			`{"type":"user","message":{"role":"user","content":[{"type":"text","text":"please take a look at the header"}]}}`,
77		}
78		for _, line := range lines {
79			if historyLineMayContainIndexedContent(line) {
80				t.Errorf("irrelevant line passed the fast-path filter: %q", line)
81			}
82		}
83	}
84	
85	// The predicate must not depend on vocabulary borrowed from benchmark tasks.
86	// These strings were the entire allowlist; matching them as such would mean the
87	// index is once again tuned to the benchmark rather than to code.
88	func TestHistoryFactSignalIsNotBenchmarkVocabulary(t *testing.T) {
89		for _, phrase := range []string{
90			"bare auth", "seed agent", "schema contract", "brainignore",
91			"attributionbasecommit", "resolve transcript path", "github workflow",
92		} {
93			if historyTextHasCodeFactSignal(phrase) {
94				t.Fatalf("benchmark phrase %q must not by itself signal a code fact", phrase)
95			}
96		}
97	}

