  1	package cli
  2	
  3	import (
  4		"database/sql"
  5		"encoding/json"
  6		"fmt"
  7		"os"
  8		"path/filepath"
  9		"strconv"
 10		"testing"
 11		"time"
 12	)
 13	
 14	func benchmarkHistoryFTSIndex(b *testing.B) historyIndex {
 15		b.Helper()
 16		if path := os.Getenv("ENTIRE_BRAIN_HISTORY_BENCH_INDEX"); path != "" {
 17			data, err := os.ReadFile(path)
 18			if err != nil {
 19				b.Fatal(err)
 20			}
 21			var index historyIndex
 22			if err := json.Unmarshal(data, &index); err != nil {
 23				b.Fatal(err)
 24			}
 25			return index
 26		}
 27		n := 60000
 28		if raw := os.Getenv("ENTIRE_BRAIN_HISTORY_BENCH_RECORDS"); raw != "" {
 29			parsed, err := strconv.Atoi(raw)
 30			if err != nil || parsed <= 0 {
 31				b.Fatalf("ENTIRE_BRAIN_HISTORY_BENCH_RECORDS=%q", raw)
 32			}
 33			n = parsed
 34		}
 35		index := historyIndex{GeneratedAt: time.Date(2026, 7, 16, 0, 0, 0, 0, time.UTC), Records: make([]historyRecord, 0, n)}
 36		for i := 0; i < n; i++ {
 37			kind := "decision"
 38			if i%7 == 0 {
 39				kind = "tool_call"
 40			}
 41			index.Records = append(index.Records, historyRecord{
 42				ID:      fmt.Sprintf("history:%024x", i+1),
 43				Kind:    kind,
 44				Branch:  "main",
 45				Path:    fmt.Sprintf("sessions/main/20260716T000000Z_%08d.jsonl", i/20),
 46				Line:    i%20 + 1,
 47				Summary: fmt.Sprintf("Decision %d validates embedding cache invalidation and model fingerprint behavior for component_%d with deterministic regression coverage.", i, i%997),
 48				Terms:   []string{"EmbeddingCache", "model_fingerprint", fmt.Sprintf("component_%d", i%997)},
 49			})
 50		}
 51		return index
 52	}
 53	
 54	func BenchmarkHistoryFTSQueryPaths(b *testing.B) {
 55		index := benchmarkHistoryFTSIndex(b)
 56		brainDir, source := writeDirectHistoryFTSFixture(b, index)
 57		query := os.Getenv("ENTIRE_BRAIN_HISTORY_BENCH_QUERY")
 58		if query == "" {
 59			query = "embedding cache invalidation fingerprint"
 60		}
 61	
 62		b.Run("json_load_then_bm25", func(b *testing.B) {
 63			b.ReportAllocs()
 64			for i := 0; i < b.N; i++ {
 65				loaded, err := loadBrainHistoryIndex(brainDir, source)
 66				if err != nil {
 67					b.Fatal(err)
 68				}
 69				if _, ok := rankHistoryViaFTS(brainDir, loaded, "history", query, 10); !ok {
 70					b.Fatal("BM25 unavailable")
 71				}
 72			}
 73		})
 74		b.Run("direct_v3_payload", func(b *testing.B) {
 75			b.ReportAllocs()
 76			for i := 0; i < b.N; i++ {
 77				if _, used, err := rankHistoryViaFreshFTS(brainDir, source, "history", query, 10); err != nil || !used {
 78					b.Fatalf("direct BM25: used=%v err=%v", used, err)
 79				}
 80			}
 81		})
 82	}
 83	
 84	// BenchmarkHistoryLegacyIdentityUpgrade measures the one-time legacy fallback
 85	// against the next invocation's direct payload path. Manifest reset is outside
 86	// the timed region; the first arm includes full truth load, identity derivation,
 87	// schema-v3 cache validation and ranking, locking, revalidation, and atomic
 88	// migration.
 89	func BenchmarkHistoryLegacyIdentityUpgrade(b *testing.B) {
 90		index := benchmarkHistoryFTSIndex(b)
 91		brainDir, strong := writeDirectHistoryFTSFixture(b, index)
 92		legacy := *strong
 93		legacy.IndexBytes = 0
 94		legacy.IndexSHA256 = ""
 95		legacy.RecordsFingerprint = ""
 96		manifest := exportManifest{SchemaVersion: brainManifestSchemaVersion, Sources: &brainSources{History: &legacy}}
 97		query := "embedding cache invalidation fingerprint"
 98	
 99		b.Run("first_legacy_upgrade", func(b *testing.B) {
100			b.ReportAllocs()
101			for i := 0; i < b.N; i++ {
102				b.StopTimer()
103				if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
104					b.Fatal(err)
105				}
106				b.StartTimer()
107				_, identity, err := loadBrainHistoryIndexWithLegacyIdentity(brainDir, &legacy)
108				if err != nil || identity == nil {
109					b.Fatalf("legacy load: identity=%+v err=%v", identity, err)
110				}
111				if _, used := rankHistoryViaLegacyDirectPayload(brainDir, &legacy, identity, "history", query, 10, historyFTSRelevanceCutoff); !used {
112					b.Fatal("legacy direct payload unavailable")
113				}
114			}
115		})
116	
117		upgraded, err := loadBrainManifest(brainDir)
118		if err != nil {
119			b.Fatal(err)
120		}
121		b.Run("second_direct", func(b *testing.B) {
122			b.ReportAllocs()
123			for i := 0; i < b.N; i++ {
124				if _, used, err := rankHistoryViaFreshFTS(brainDir, upgraded.Sources.History, "history", query, 10); err != nil || !used {
125					b.Fatalf("direct payload: used=%v err=%v", used, err)
126				}
127			}
128		})
129	}
130	
131	func BenchmarkHistoryLegacyIdentityLockRecheck(b *testing.B) {
132		index := benchmarkHistoryFTSIndex(b)
133		brainDir, source := writeDirectHistoryFTSFixture(b, index)
134		b.ReportAllocs()
135		b.ResetTimer()
136		for i := 0; i < b.N; i++ {
137			fingerprint, err := historyIndexFingerprintForIdentityRecheck(brainDir, source.IndexPath, source.IndexBytes)
138			if err != nil || fingerprint != source.IndexSHA256 {
139				b.Fatalf("stream identity: fingerprint=%q err=%v", fingerprint, err)
140			}
141		}
142	}
143	
144	func BenchmarkHistoryFTSStorageDelta(b *testing.B) {
145		b.StopTimer()
146		index := benchmarkHistoryFTSIndex(b)
147		v2Brain, _ := writeDirectHistoryFTSFixture(b, index)
148		v2Bytes := sqliteArtifactBytes(historyFTSDBPath(v2Brain))
149	
150		v1Path := filepath.Join(b.TempDir(), "history-v1.sqlite")
151		if err := buildHistoryFTSV1Fixture(v1Path, index); err != nil {
152			b.Fatal(err)
153		}
154		v1Bytes := sqliteArtifactBytes(v1Path)
155		b.ReportMetric(float64(v1Bytes), "v1_bytes")
156		b.ReportMetric(float64(v2Bytes), "v2_bytes")
157		b.ReportMetric(100*(float64(v2Bytes)-float64(v1Bytes))/float64(v1Bytes), "v2_delta_pct")
158		b.StartTimer()
159		for i := 0; i < b.N; i++ {
160			// Artifacts are built outside the timed region; this benchmark reports
161			// their exact closed-database footprint through custom metrics.
162		}
163	}
164	
165	func sqliteArtifactBytes(path string) int64 {
166		var total int64
167		for _, candidate := range []string{path, path + "-wal", path + "-shm"} {
168			if info, err := os.Stat(candidate); err == nil {
169				total += info.Size()
170			}
171		}
172		return total
173	}
174	
175	func buildHistoryFTSV1Fixture(path string, index historyIndex) error {
176		db, err := sql.Open(sqliteDriverName, path)
177		if err != nil {
178			return err
179		}
180		defer db.Close()
181		if _, err := db.Exec(`CREATE VIRTUAL TABLE history_fts USING fts5(content, kind UNINDEXED, rec_order UNINDEXED, tokenize='porter unicode61')`); err != nil {
182			return err
183		}
184		tx, err := db.Begin()
185		if err != nil {
186			return err
187		}
188		defer tx.Rollback()
189		stmt, err := tx.Prepare(`INSERT INTO history_fts(content, kind, rec_order) VALUES (?, ?, ?)`)
190		if err != nil {
191			return err
192		}
193		defer stmt.Close()
194		for i, record := range index.Records {
195			if _, err := stmt.Exec(historyFTSContent(record), record.Kind, i); err != nil {
196				return err
197			}
198		}
199		return tx.Commit()
200	}

