593	// TestBriefFocusedHistoryNeverRebuildsFTSFromMergedRecords locks the contract
594	// behind Bugbot PR #77: the on-disk BM25 store must only ever rank the
595	// LONG-TERM tier.
596	//
597	// openHistoryFTS keys freshness on historyFTSIdentityFromIndex (records
598	// fingerprint + count). Handing it a merged (short-term-inclusive) index
599	// therefore does not just read the wrong rows: the identity mismatches, so the
600	// store is REBUILT from the merged set, and every later long-term reader finds
601	// it stale and rebuilds it back. This test drives the real
602	// brainBriefFocusedHistoryMatches against a two-tier view and proves the store
603	// is still fresh for the long-term index afterwards. Passing the merged set
604	// (the pre-fix behavior) fails it.
605	func TestBriefFocusedHistoryNeverRebuildsFTSFromMergedRecords(t *testing.T) {
606		brainDir, _, _ := shortTermFixture(t)
607		buildShortTerm(t, brainDir)
608		manifest, err := loadBrainManifest(brainDir)
609		if err != nil {
610			t.Fatal(err)
611		}
612		fresh, err := loadFreshHistory(brainDir, manifest.Sources.History)
613		if err != nil {
614			t.Fatal(err)
615		}
616		if len(fresh.overlay) == 0 {
617			t.Fatal("fixture invalid: the two-tier view needs a non-empty overlay")
618		}
619		longTerm := fresh.index
620		merged := historyIndex{GeneratedAt: longTerm.GeneratedAt, Records: fresh.mergedRecords()}
621		if historyFTSIdentityFromIndex(longTerm) == historyFTSIdentityFromIndex(merged) {
622			t.Fatal("fixture invalid: the merged and long-term identities must differ for this to prove anything")
623		}
624	
625		// Prime the store from the long-term tier. Skip where SQLite/FTS5 is not
626		// compiled in: there is no store to corrupt.
627		primed, err := openHistoryFTS(brainDir, longTerm)
628		if err != nil || primed == nil {
629			t.Skipf("history FTS unavailable in this build: %v", err)
630		}
631		primed.Close()
632	
633		matches := brainBriefFocusedHistoryMatches(
634			brainDir,
635			fresh,
636			semanticRecord{Name: "gzip", QualifiedName: "gzip"},
637			5,
638			sessionReadGuard{},
639		)
640		_ = matches // ranking output is not the contract under test; the store identity is.
641	
642		after, err := openHistoryFTSIfFresh(brainDir, longTerm)
643		if err != nil {
644			t.Fatalf("history FTS unreadable after the focused lookup: %v", err)
645		}
646		if after == nil {
647			t.Fatal("focused history left the BM25 store stale for the long-term index: it was rebuilt from a merged record set")
648		}
649		after.Close()
650	}
