660		db, err := openHistoryFTSIfFresh(brainDir, index)
661		if err != nil || db == nil {
662			t.Fatalf("open fixture: db=%v err=%v", db, err)
663		}
664		defer db.Close()
665		var schema string
666		if err := db.QueryRow(`SELECT sql FROM sqlite_master WHERE name = 'history_records'`).Scan(&schema); err != nil {
667			t.Fatal(err)
668		}
669		legacySchema := strings.Replace(schema, "id TEXT NOT NULL,", "id TEXT NOT NULL UNIQUE,", 1)
670		if legacySchema == schema {
671			t.Fatal("fixture could not restore the old UNIQUE(id) table definition")
672		}
673		tx, err := db.Begin()
674		if err != nil {
675			t.Fatal(err)
676		}
677		defer tx.Rollback()
678		for _, stmt := range []string{
679			`ALTER TABLE history_records RENAME TO saved_records`,
680			legacySchema,
681			`INSERT INTO history_records SELECT * FROM saved_records`,
682			`DROP TABLE saved_records`,
683			`UPDATE history_fts_meta SET value = '1' WHERE key = 'payload_schema'`,
684		} {
685			if _, err := tx.Exec(stmt); err != nil {
686				t.Fatalf("restore legacy schema: %v", err)
687			}
688		}
689		if err := tx.Commit(); err != nil {
690			t.Fatal(err)
691		}
692		if !historyFTSFresh(db, index) {
693			t.Fatal("unchanged history should reuse the read-compatible legacy cache")
694		}
695		if err := db.Close(); err != nil {
696			t.Fatal(err)
697		}
698		got, used, err := rankHistoryViaFreshFTSCutoff(brainDir, source, conversationKind, "shared retrieval marker", 10, 0)
699		if err != nil || !used || len(got) != 1 {
700			t.Fatalf("legacy direct read: used=%v matches=%d err=%v", used, len(got), err)
701		}
702	
703		index.Records = append(index.Records, historyRecord{
704			ID: index.Records[0].ID, Kind: conversationKind, Branch: "feature", Path: "sessions/feature/two.jsonl", Line: 1, Summary: "beta shared retrieval marker",
705		})
706		fresh, err := openHistoryFTSIfFresh(brainDir, index)
707		if fresh != nil {
708			fresh.Close()
709			t.Fatal("changed source incorrectly reused the legacy cache")
710		}
711		if err != nil {
712			t.Fatal(err)
713		}
714		rebuilt, err := openHistoryFTS(brainDir, index)
715		if err != nil {
716			t.Fatalf("rebuild for duplicate IDs: %v", err)
717		}
718		defer rebuilt.Close()
719		var rows, ids int
720		if err := rebuilt.QueryRow(`SELECT count(*), count(DISTINCT id) FROM history_records`).Scan(&rows, &ids); err != nil {
721			t.Fatal(err)
722		}
723		if rows != 2 || ids != 1 || !historyFTSFresh(rebuilt, index) {
724			t.Fatalf("rebuilt cache: rows=%d distinct IDs=%d; want two fresh rows sharing an ID", rows, ids)
725		}
726	}

