  1	package cli
  2	
  3	import (
  4		"fmt"
  5		"strings"
  6		"testing"
  7	)
  8	
  9	// fuseTieDigests is an 8-way exact tie. sort.SliceStable leaves
 10	// comparator-equal elements in input order, and the input order of
 11	// fuseScoredRankLists is a Go map range, which is re-randomized on every
 12	// iteration. With an incomplete comparator a single call therefore has a
 13	// 1/8! (~1 in 40,320) chance of landing on the sorted order, so the assertion
 14	// below fails on effectively every run and certainly within the loop.
 15	var fuseTieDigests = []string{"d01", "d02", "d03", "d04", "d05", "d06", "d07", "d08"}
 16	
 17	func fuseTieLists(records []historyRecord) [][]scoredHistoryRecord {
 18		lists := make([][]scoredHistoryRecord, 0, len(records))
 19		for _, record := range records {
 20			// One record per list, all at rank 0: every entry earns the identical
 21			// RRF contribution, so score can never break the tie.
 22			lists = append(lists, []scoredHistoryRecord{{Record: record}})
 23		}
 24		return lists
 25	}
 26	
 27	func fuseOrder(fused []scoredHistoryRecord, field func(historyRecord) string) string {
 28		parts := make([]string, len(fused))
 29		for i, s := range fused {
 30			parts[i] = field(s.Record)
 31		}
 32		return strings.Join(parts, " ")
 33	}
 34	
 35	// TestFuseScoredRankListsOrdersDegradedCopiesDeterministically pins the
 36	// determinism contract of the shared history/conversation RRF merge.
 37	//
 38	// fuseScoredRankLists fuses by historyRecordReplacementKey. That key
 39	// deliberately keeps degraded copies of one exchange distinct: when a record
 40	// has no session id, recordReplacementKey falls back to the source digest
 41	// ("It prevents two degraded sessions from replacing one another merely
 42	// because an old producer emitted the same exchange ID"). Those copies reach
 43	// the final sort as separate entries whose id, branch, session id, path and
 44	// line are all equal, so the comparator must still impose a total order on
 45	// them — otherwise the same query returns a different ranking from one call to
 46	// the next.
 47	func TestFuseScoredRankListsOrdersDegradedCopiesDeterministically(t *testing.T) {
 48		t.Parallel()
 49		records := make([]historyRecord, 0, len(fuseTieDigests))
 50		for _, digest := range fuseTieDigests {
 51			records = append(records, historyRecord{
 52				ID:           conversationIDPrefix + "abc123",
 53				Kind:         conversationKind,
 54				Branch:       "main",
 55				SessionID:    "", // degraded identity: key.Session falls back to SourceDigest
 56				Path:         "sessions/main/20260801T000000Z_session.jsonl",
 57				Line:         7,
 58				EndLine:      8,
 59				TurnOrdinal:  4,
 60				Summary:      "exchange copy " + digest,
 61				SourceDigest: digest,
 62				ContentRole:  conversationContentRole,
 63			})
 64		}
 65		keys := map[historyRecordReplacementKey]struct{}{}
 66		for _, record := range records {
 67			keys[recordReplacementKey(record)] = struct{}{}
 68		}
 69		if len(keys) != len(records) {
 70			t.Fatalf("fixture invalid: %d degraded copies collapsed into %d fusion identities", len(records), len(keys))
 71		}
 72	
 73		lists := fuseTieLists(records)
 74		want := strings.Join(fuseTieDigests, " ")
 75		for run := 0; run < 500; run++ {
 76			fused := fuseScoredRankLists(lists, len(records))
 77			if len(fused) != len(records) {
 78				t.Fatalf("run %d: fused %d records, want %d", run, len(fused), len(records))
 79			}
 80			got := fuseOrder(fused, func(r historyRecord) string { return r.SourceDigest })
 81			if got != want {
 82				t.Fatalf("run %d: fused order = %q, want %q; the same input produced a different ranking", run, got, want)
 83			}
 84		}
 85	}
 86	
 87	// TestFuseScoredRankListsTieBreakCoversTheFusionKey guards the invariant
 88	// directly: every field that can make two fusion keys distinct must also be
 89	// able to order the two records. Kind is part of the key for every record.
 90	func TestFuseScoredRankListsTieBreakCoversTheFusionKey(t *testing.T) {
 91		t.Parallel()
 92		kinds := []string{"k1", "k2", "k3", "k4", "k5", "k6", "k7", "k8"}
 93		records := make([]historyRecord, 0, len(kinds))
 94		for i, kind := range kinds {
 95			records = append(records, historyRecord{
 96				ID:      "history:same",
 97				Kind:    kind, // distinct fusion key, identical in every compared field
 98				Path:    "sessions/main/20260801T000000Z_session.jsonl",
 99				Line:    3,
100				Summary: fmt.Sprintf("record %d", i),
101			})
102		}
103		keys := map[historyRecordReplacementKey]struct{}{}
104		for _, record := range records {
105			keys[recordReplacementKey(record)] = struct{}{}
106		}
107		if len(keys) != len(records) {
108			t.Fatalf("fixture invalid: %d kinds collapsed into %d fusion identities", len(records), len(keys))
109		}
110	
111		lists := fuseTieLists(records)
112		want := strings.Join(kinds, " ")
113		for run := 0; run < 500; run++ {
114			fused := fuseScoredRankLists(lists, len(records))
115			if len(fused) != len(records) {
116				t.Fatalf("run %d: fused %d records, want %d", run, len(fused), len(records))
117			}
118			got := fuseOrder(fused, func(r historyRecord) string { return r.Kind })
119			if got != want {
120				t.Fatalf("run %d: fused order = %q, want %q; the same input produced a different ranking", run, got, want)
121			}
122		}
123	}

