 18	func TestHistorySessionInventoryRejectsFIFOAndSocketWithoutBlocking(t *testing.T) {
 19		for _, kind := range []string{"fifo", "socket"} {
 20			t.Run(kind, func(t *testing.T) {
 21				brainDir, err := os.MkdirTemp("/tmp", "eb-history-input-")
 22				if err != nil {
 23					t.Fatal(err)
 24				}
 25				t.Cleanup(func() { _ = os.RemoveAll(brainDir) })
 26				dir := filepath.Join(brainDir, exportSessionsDirectory, "main")
 27				if err := os.MkdirAll(dir, 0o700); err != nil {
 28					t.Fatal(err)
 29				}
 30				leaf := filepath.Join(dir, "hostile.jsonl")
 31				var listener net.Listener
 32				switch kind {
 33				case "fifo":
 34					if err := unix.Mkfifo(leaf, 0o600); err != nil {
 35						t.Fatal(err)
 36					}
 37				case "socket":
 38					listener, err = net.Listen("unix", leaf)
 39					if err != nil {
 40						t.Fatal(err)
 41					}
 42					t.Cleanup(func() { _ = listener.Close() })
 43				}
 44	
 45				done := make(chan error, 1)
 46				go func() {
 47					inventory, err := collectHistorySessionInventory(context.Background(), brainDir)
 48					if inventory != nil {
 49						_ = inventory.Close()
 50					}
 51					done <- err
 52				}()
 53				select {
 54				case err := <-done:
 55					if !errors.Is(err, errHistorySessionInventoryDegraded) || memoryErrorCode(err) != memoryErrSessionInventory {
 56						t.Fatalf("inventory error = %v, code=%q", err, memoryErrorCode(err))
 57					}
 58				case <-time.After(2 * time.Second):
 59					t.Fatalf("inventory blocked on %s", kind)
 60				}
 61			})
 62		}
 63	}
