	// Seed the cursor so "no change" is reachable (a zero cursor forces refresh).
	if err := saveWatchCursor(cursorPath, watchCursor{LastFingerprint: "same", LastRefreshAt: time.Date(2026, 8, 7, 11, 0, 0, 0, time.UTC)}); err != nil {
		t.Fatal(err)
