121	// TestRawHistoryFallbackRetainsFallbackOnlyMatch names the safety property for
122	// future negative-result optimizations: an indexed miss is not proof of
123	// absence while raw exported history can still contain a valid match.
124	//
125	// Mutation proof: overlay agent_surface.go and replace
126	//
127	//	rawMatches, rawErr := rawHistoryMatcher(status.Brain.Path, task, nil, briefOpts.limit, rawProfile)
128	//
129	// with `_ = rawProfile` followed by
130	// `rawMatches, rawErr := []brainTextMatch(nil), error(nil)`. This test fails
131	// with "end-to-end brief lost fallback-only match"; the production file is
132	// never modified.
133	func TestRawHistoryFallbackRetainsFallbackOnlyMatch(t *testing.T) {
134		const marker = "FALLBACK_ONLY_HISTORY_MARKER"
135		fixture := newBrainBriefRawHistoryEndToEndFixture(t)
136		storage, err := repoStoragePaths(context.Background(), fixture.opts.Runner, fixture.opts.Env, fixture.opts.Env.RepoRoot)
137		if err != nil {
138			t.Fatal(err)
139		}
140		brainDir := storage.BrainDir
141		generatedAt := time.Date(2026, 8, 7, 12, 0, 0, 0, time.UTC)
142		index := historyIndex{GeneratedAt: generatedAt, Records: []historyRecord{{
143			ID: "indexed-unrelated", Kind: "decision", Path: "sessions/main/old.jsonl",
144			Line: 1, Summary: "an unrelated indexed decision",
145		}}}
146		if got := rankHistoryRecordsScored(index, "history", marker, 8, 0); len(got) != 0 {
147			t.Fatalf("fixture marker unexpectedly appeared in the index: %+v", got)
148		}
149		source := &historySourceManifest{
150			GeneratedAt: generatedAt,
151			IndexPath:   historyIndexPath,
152			Records:     len(index.Records),
153		}
154		if err := publishHistoryComparisonIndex(brainDir, index, source); err != nil {
155			t.Fatal(err)
156		}
157	
158		// Add the marker only after the unrelated nonempty index was persisted.
159		// The real brief orchestration must execute the raw-history fallback.
160		fallbackPath := filepath.Join(brainDir, "notes", "fallback.md")
161		if err := os.MkdirAll(filepath.Dir(fallbackPath), 0o700); err != nil {
162			t.Fatal(err)
163		}
164		if err := os.WriteFile(fallbackPath, []byte("decision evidence "+marker+" remains available\n"), 0o600); err != nil {
165			t.Fatal(err)
166		}
167		fixture.task = marker
168		var out bytes.Buffer
169		if err := runBrainBriefRawHistoryEndToEndInto(&out, fixture, brainBriefRawHistoryMatchesObserved); err != nil {
170			t.Fatal(err)
171		}
172		var report brainBriefJSONReport
173		if err := json.Unmarshal(out.Bytes(), &report); err != nil {
174			t.Fatalf("decode brief: %v\n%s", err, out.String())
175		}
176		if !report.Status.Sources.History {
177			t.Fatal("fixture did not expose the persisted history source")
178		}
179		if len(report.History.Matches) != 1 || report.History.Matches[0].Path != "notes/fallback.md" {
180			t.Fatalf("end-to-end brief lost fallback-only match: %+v; warnings=%v; packet=%s", report.History.Matches, report.Warnings, out.String())
