252	// BenchmarkHistoryRetrievalEquivalentPaths compares the persisted direct
253	// payload accelerator with the JSON-load path. Correctness is checked before
254	// the timer so a faster but behaviorally different path cannot produce a
255	// publishable benchmark result.
256	func BenchmarkHistoryRetrievalEquivalentPaths(b *testing.B) {
257		brainDir, source := assertHistoryRetrievalEquivalentPaths(b, 6000)
258		const query = "retrieval cache invalidation source provenance"
259	
260		b.Run("json_load_then_rank", func(b *testing.B) {
261			b.ReportAllocs()
