263				loaded, loadErr := loadBrainHistoryIndex(brainDir, source)
264				if loadErr != nil {
265					b.Fatal(loadErr)
266				}
267				results, ranked := rankHistoryViaFTS(brainDir, loaded, "history", query, 10)
268				if !ranked {
269					b.Fatal("JSON-backed FTS unavailable")
270				}
271				historyRetrievalEquivalenceSink = results
272			}
273		})
274		b.Run("direct_payload", func(b *testing.B) {
275			b.ReportAllocs()
276			for i := 0; i < b.N; i++ {
277				results, direct, rankErr := rankHistoryViaFreshFTS(brainDir, source, "history", query, 10)
278				if rankErr != nil || !direct {
279					b.Fatalf("direct FTS: used=%v err=%v", direct, rankErr)
280				}
281				historyRetrievalEquivalenceSink = results
282			}
283		})
284	}

