 29			t.Errorf("pi assistant turn not indexed as narrative: %+v", fragments)
 30		}
 31	
 32		// User turns yield exactly one request fragment (scan-cache v4) — present
 33		// for trajectory surfaces (handoff, midtask mining), still excluded from
 34		// general ranking — and never a narrative fragment.
