 36		if fragments := extractHistoryJSONFragments(user); len(fragments) != 1 || fragments[0].Source != "user_prompt" {
 37			t.Errorf("pi user turn should index as exactly one user_prompt fragment: %+v", fragments)
 38		}
 39	
 40		// toolResult content is mined for code facts like Claude tool_result blocks.
 41		toolResult := parse(`{"type":"message","message":{"role":"toolResult","toolName":"bash","content":[{"type":"text","text":"state.transcriptPath = \"sessions/main\""}]}}`)
 42		fragments = extractHistoryJSONFragments(toolResult)
 43		if len(fragments) == 0 || fragments[0].Source != "tool_result_fact" {
 44			t.Errorf("pi toolResult with code-fact signal not indexed: %+v", fragments)
 45		}
 46	}
