 48	func TestScanHistoryFileOpencodeDocument(t *testing.T) {
 49		doc := `{
 50	  "info": {"id": "ses_x"},
 51	  "messages": [
 52	    {
 53	      "info": {"role": "user"},
 54	      "parts": [{"type": "text", "text": "Remove the header bottom border"}]
 55	    },
 56	    {
 57	      "info": {"role": "assistant"},
 58	      "parts": [
 59	        {"type": "tool", "tool": "edit", "state": {"output": "huge tool output"}},
 60	        {"type": "tool", "tool": "bash", "state": {"output": "borderWidth = 0"}},
 61	        {"type": "text", "text": "The root cause is the duplicated border; removed both."}
 62	      ]
 63	    }
 64	  ]
 65	}`
 66		dir := t.TempDir()
 67		path := filepath.Join(dir, "20260604T120000Z-ses_x.jsonl")
