 69			t.Fatal(err)
 70		}
 71		records, err := scanHistoryFile(dir, path)
 72		if err != nil {
 73			t.Fatalf("scanHistoryFile: %v", err)
 74		}
 75		if len(records) == 0 {
 76			t.Fatal("document-form transcript indexed to nothing; the line scanner cannot parse it and the document path must take over")
 77		}
