105		// JSONL files must still go through the line scanner.
106		jsonl := filepath.Join(dir, "20260604T120001Z-jsonl.jsonl")
107		line := `{"type":"message","message":{"role":"assistant","content":[{"type":"text","text":"The root cause is the resolve transcript path fallback."}]}}`
108		if err := os.WriteFile(jsonl, []byte(line+"\n"), 0o600); err != nil {
109			t.Fatal(err)
110		}
111		records, err = scanHistoryFile(dir, jsonl)
112		if err != nil {
113			t.Fatalf("scanHistoryFile(jsonl): %v", err)
114		}
115		if len(records) == 0 {
116			t.Error("JSONL transcript no longer indexed after the document-path change")
117		}
118	}
