120	func TestFirstUserRequestPiAndOpencode(t *testing.T) {
121		pi := `{"type":"message","message":{"role":"toolResult","content":[{"type":"text","text":"ls output"}]}}` + "\n" +
122			`{"type":"message","message":{"role":"user","content":[{"type":"text","text":"Make the dashboard cohesive"}]}}` + "\n"
123		if got := firstUserRequest(pi); got != "Make the dashboard cohesive" {
124			t.Errorf("firstUserRequest(pi) = %q", got)
125		}
