128	  "messages": [
129	    {
130	      "info": {"role": "assistant"},
131	      "parts": [{"type": "text", "text": "Hello"}]
132	    },
133	    {
134	      "info": {"role": "user"},
135	      "parts": [{"type": "text", "text": "Remove the header bottom border"}]
136	    }
137	  ]
138	}`
