   194	func assertHistoryRetrievalEquivalentPaths(tb testing.TB, size int) (string, *historySourceManifest) {
   195		tb.Helper()
   196		brainDir, source := writeDirectHistoryFTSFixture(tb, historyRetrievalEquivalenceIndex(size))
   197		loaded, err := loadBrainHistoryIndex(brainDir, source)
   198		if err != nil {
   199			tb.Fatal(err)
   200		}
   201		cases := []struct {
   202			name         string
   203			kind         string
   204			query        string
   205			limit        int
   206			wantNonEmpty bool
   207		}{
   208			{name: "positive", kind: "history", query: "retrieval cache invalidation source provenance", limit: 10, wantNonEmpty: true},
   209			{name: "honest_empty", kind: "history", query: "xylophone zebra quokka", limit: 10},
   210			{name: "discriminating_top_k", kind: "decisions", query: "component_7 source provenance", limit: 3, wantNonEmpty: true},
   211			{name: "kind_filtered_empty", kind: "tool-paths", query: "retrieval cache invalidation source provenance", limit: 10},
   212		}
   213		for _, tc := range cases {
   214			want, ok := rankHistoryViaFTS(brainDir, loaded, tc.kind, tc.query, tc.limit)
   215			if !ok {
   216				tb.Fatalf("%s JSON-backed preflight unavailable", tc.name)
   217			}
   218			if tc.wantNonEmpty && len(want) == 0 {
   219				tb.Fatalf("%s JSON-backed preflight returned no results", tc.name)
   220			}
   221			if !tc.wantNonEmpty && len(want) != 0 {
   222				tb.Fatalf("%s must have no matches, got %d", tc.name, len(want))
   223			}
   224			if len(want) > tc.limit {
   225				tb.Fatalf("%s exceeded result limit: got %d, limit %d", tc.name, len(want), tc.limit)
   226			}
   227			got, used, rankErr := rankHistoryViaFreshFTS(brainDir, source, tc.kind, tc.query, tc.limit)
   228			if rankErr != nil || !used {
   229				tb.Fatalf("%s direct preflight: used=%v err=%v", tc.name, used, rankErr)
   230			}
   231			if !reflect.DeepEqual(got, want) {
   232				tb.Fatalf("%s direct payload differs from JSON-backed ranking\ndirect: %+v\nJSON: %+v", tc.name, got, want)
   233			}
   234		}
   235		return brainDir, source
   236	}
