   242				ID: fmt.Sprintf("history:%08d", i), Kind: "decision", Branch: "main",
   243				Path:    fmt.Sprintf("sessions/main/20260807T%06dZ_%04d.jsonl", i%240000, i/20),
   244				Line:    i%20 + 1,
   245				Summary: fmt.Sprintf("Decision %d validates retrieval cache invalidation and source provenance for component_%d.", i, i%113),
   246				Terms:   []string{"retrieval_cache", "source_provenance", fmt.Sprintf("component_%d", i%113)},
   247			})
   248		}
   249		return index
