   137	  ]
   138	}`
   139		if got := firstUserRequest(doc); got != "Remove the header bottom border" {
   140			t.Errorf("firstUserRequest(opencode document) = %q", got)
   141		}
   142	}
   143	
   144	// TestExtractHistoryJSONFragmentsRequestRecords covers the v4 re-introduction
   145	// of request extraction: real user turns across dialects become request-kind
   146	// fragments, wrapper injections never do, and request records stay excluded
   147	// from general ranking (the v3 noise decision, unchanged).
   148	func TestExtractHistoryJSONFragmentsRequestRecords(t *testing.T) {
   149		cases := []struct {
   150			name string
   151			line string
   152			want string // expected request text, "" = no request fragment
   153		}{
   154			{"claude user turn", `{"type":"user","message":{"content":"add retry backoff"}}`, "add retry backoff"},
   155			{"codex user_message", `{"type":"event_msg","payload":{"type":"user_message","message":"why does flush stay dirty"}}`, "why does flush stay dirty"},
   156			{"pi user turn", `{"type":"message","message":{"role":"user","content":[{"type":"text","text":"make it cohesive"}]}}`, "make it cohesive"},
   157			{"wrapper filtered", `{"type":"user","message":{"content":"<local-command-caveat>Caveat: local commands"}}`, ""},
   158			{"tool result is not a request", `{"type":"user","message":{"content":[{"type":"tool_result","content":"blob"}]}}`, ""},
   159			{"assistant is not a request", `{"type":"assistant","message":{"content":[{"type":"text","text":"decided to keep it"}]}}`, ""},
   160		}
   161		for _, c := range cases {
   162			var obj map[string]any
   163			if err := json.Unmarshal([]byte(c.line), &obj); err != nil {
   164				t.Fatalf("%s: %v", c.name, err)
   165			}
   166			var got []historyFragment
   167			for _, f := range extractHistoryJSONFragments(obj) {
   168				if f.Source == "user_prompt" {
   169					got = append(got, f)
   170				}
   171			}
   172			if c.want == "" {
   173				if len(got) != 0 {
   174					t.Errorf("%s: unexpected request fragment %+v", c.name, got)
   175				}
   176				continue
   177			}
   178			if len(got) != 1 || got[0].Text != c.want {
   179				t.Errorf("%s: request fragment = %+v, want text %q", c.name, got, c.want)
   180			}
   181			if kinds := classifyHistoryFragment(got[0]); len(kinds) != 1 || kinds[0] != "request" {
   182				t.Errorf("%s: user_prompt should classify as exactly [request], got %v", c.name, kinds)
   183			}
   184		}
   185	
   186		// The general ranking arm must keep excluding request records.
   187		index := historyIndex{Records: []historyRecord{
   188			{ID: "r1", Kind: "request", Path: "p", Line: 1, Summary: "add retry backoff to the fetcher"},
   189			{ID: "r2", Kind: "decision", Path: "p", Line: 2, Summary: "retry backoff doubles per attempt"},
   190		}}
   191		for _, r := range rankHistoryRecordsScored(index, "history", "retry backoff", 10, 0) {
   192			if r.Record.Kind == "request" {
   193				t.Fatalf("request record leaked into general ranking: %+v", r.Record)
   194			}
   195		}
   196	}

