  1	package cli
  2	
  3	import (
  4		"os"
  5		"path/filepath"
  6		"strings"
  7		"testing"
  8		"time"
  9	)
 10	
 11	// A brain whose session export never produced a source -- `setup` on a machine
 12	// with no host CLI is the ordinary way to get one -- still publishes a history
 13	// projection and its receipt. That receipt used to read back as
 14	// memory_source_stale immediately after being written, because the publisher
 15	// recorded an EMPTY SessionsFingerprint and the checked reader treats empty as
 16	// unproven. The prescribed remedy, `memory repair`, republished the same empty
 17	// fingerprint it had just rejected, so the state was unrepairable by design.
 18	func TestSessionlessBrainReadsBackItsOwnProjectionReceipt(t *testing.T) {
 19		now := time.Date(2026, 9, 1, 12, 0, 0, 0, time.UTC)
 20		brainDir := t.TempDir()
 21		manifest := exportManifest{
 22			SchemaVersion: brainManifestSchemaVersion, GeneratedAt: now,
 23			RepoKey: "test/sessionless", DefaultBranch: "main",
 24			// No Sessions source at all: the export failed or never ran.
 25			Sources: &brainSources{},
 26		}
 27		if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
 28			t.Fatal(err)
 29		}
 30		// The sessions tree exists and is empty, exactly as a failed or
 31		// zero-session export leaves it.
 32		if err := os.MkdirAll(filepath.Join(brainDir, exportSessionsDirectory, "main"), 0o700); err != nil {
 33			t.Fatal(err)
 34		}
 35		source, err := writeBrainHistoryIndexAndSource(brainDir, now, nil)
 36		if err != nil {
 37			t.Fatalf("publish history projection: %v", err)
 38		}
 39		if source.SessionsFingerprint != sessionSourceFingerprintAbsent {
 40			t.Fatalf("sessionless brain must publish a nameable fingerprint, got %q", source.SessionsFingerprint)
 41		}
 42		if got := brainSessionsFingerprint(brainDir); got != sessionSourceFingerprintAbsent {
 43			t.Fatalf("current fingerprint = %q, want %q", got, sessionSourceFingerprintAbsent)
 44		}
 45	
 46		published, err := loadBrainManifest(brainDir)
 47		if err != nil {
 48			t.Fatal(err)
 49		}
 50		_, state, stateErr := loadProjectionStateChecked(brainDir, published.Sources.History)
 51		if state != projectionStateCurrent {
 52			t.Fatalf("freshly published receipt reads back as %q (%v); want %q",
 53				state, stateErr, projectionStateCurrent)
 54		}
 55	}
 56	
 57	// A receipt written by a binary that predates fingerprinting carries "". That
 58	// stays unproven against a brain that HAS sessions, and is accepted only
 59	// against one that provably has none -- the compatibility path that lets an
 60	// already-broken brain heal without a repair run.
 61	func TestEmptyRecordedFingerprintIsCurrentOnlyAgainstAnAbsentSource(t *testing.T) {
 62		for _, tc := range []struct {
 63			name              string
 64			recorded, current string
 65			want              bool
 66		}{
 67			{name: "legacy receipt, no sessions source", recorded: "", current: sessionSourceFingerprintAbsent, want: true},
 68			{name: "legacy receipt, real sessions source", recorded: "", current: "sha256:abc", want: false},
 69			{name: "unreadable manifest", recorded: "sha256:abc", current: "", want: false},
 70			{name: "matching", recorded: "sha256:abc", current: "sha256:abc", want: true},
 71			{name: "drifted", recorded: "sha256:abc", current: "sha256:def", want: false},
 72			{name: "absent both sides", recorded: sessionSourceFingerprintAbsent, current: sessionSourceFingerprintAbsent, want: true},
 73			{name: "was absent, now has sessions", recorded: sessionSourceFingerprintAbsent, current: "sha256:abc", want: false},
 74		} {
 75			t.Run(tc.name, func(t *testing.T) {
 76				if got := sessionSourceFingerprintCurrent(tc.recorded, tc.current); got != tc.want {
 77					t.Fatalf("sessionSourceFingerprintCurrent(%q, %q) = %v, want %v",
 78						tc.recorded, tc.current, got, tc.want)
 79				}
 80			})
 81		}
 82	}
 83	
 84	// A transcript carrying one line over historyMaxLineBytes drops out of the
 85	// projection entirely -- records and exchanges both. The only evidence used to
 86	// be a bare "bufio.Scanner: token too long" naming no file, so the session
 87	// count silently disagreed with the manifest and no reader could tell which
 88	// session had gone missing.
 89	func TestOversizedTranscriptLineWarningNamesTheTranscript(t *testing.T) {
 90		now := time.Date(2026, 9, 1, 12, 0, 0, 0, time.UTC)
 91		brainDir := t.TempDir()
 92		rel := "sessions/main/20260901T000000Z_huge.jsonl"
 93		huge := `{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"Decision: ` +
 94			strings.Repeat("x", historyMaxLineBytes+1) + `"}]}}`
 95		writeBundleTestFile(t, filepath.Join(brainDir, filepath.FromSlash(rel)), huge+"\n")
 96	
 97		manifest := exportManifest{
 98			SchemaVersion: brainManifestSchemaVersion, GeneratedAt: now,
 99			RepoKey: "test/huge", DefaultBranch: "main",
100			Sources: &brainSources{Sessions: &sessionSourceManifest{
101				GeneratedAt: now, DefaultBranch: "main",
102				Sessions: []exportSession{{
103					SessionID: "huge-sess", Branch: "main", Agent: "claude",
104					LatestCheckpoint: "cp1", TranscriptPath: rel, CreatedAt: now,
105				}},
106			}},
107		}
108		if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
109			t.Fatal(err)
110		}
111		source, err := writeBrainHistoryIndexAndSource(brainDir, now, nil)
112		if err != nil {
113			t.Fatalf("publish history projection: %v", err)
114		}
115		if source.Records != 0 {
116			t.Fatalf("expected the oversized transcript to contribute nothing, got %d records", source.Records)
117		}
118		joined := strings.Join(source.Warnings, "\n")
119		if !strings.Contains(joined, rel) {
120			t.Fatalf("a dropped session must be attributable; warnings = %q", joined)
121		}
122	}

