 10	)
 11	
 12	func BenchmarkHistoryTranscriptRefresh(b *testing.B) {
 13		for _, fileCount := range []int{48, 512} {
 14			b.Run(fmt.Sprintf("full-rebuild/%d-files", fileCount), func(b *testing.B) {
 15				brainDir, corpusBytes := historyRefreshBenchmarkFixture(b, fileCount)
 16				cachePath := filepath.Join(brainDir, filepath.FromSlash(historyScanCachePath))
 17				now := time.Date(2026, 7, 17, 12, 0, 0, 0, time.UTC)
 18				b.ReportAllocs()
 19				b.SetBytes(corpusBytes)
 20				b.ResetTimer()
 21				for i := 0; i < b.N; i++ {
 22					if err := os.Remove(cachePath); err != nil && !os.IsNotExist(err) {
 23						b.Fatal(err)
 24					}
 25					if _, _, err := buildBrainHistoryIndex(brainDir, now, nil); err != nil {
 26						b.Fatal(err)
 27					}
 28				}
 29			})
 30	
 31			b.Run(fmt.Sprintf("unchanged/%d-files", fileCount), func(b *testing.B) {
 32				brainDir, corpusBytes := historyRefreshBenchmarkFixture(b, fileCount)
 33				now := time.Date(2026, 7, 17, 12, 0, 0, 0, time.UTC)
 34				if _, err := writeBrainHistoryIndexAndSource(brainDir, now, nil); err != nil {
 35					b.Fatal(err)
 36				}
 37				manifest, err := loadBrainManifest(brainDir)
 38				if err != nil {
 39					b.Fatal(err)
 40				}
 41				b.ReportAllocs()
 42				b.SetBytes(corpusBytes)
 43				b.ResetTimer()
 44				for i := 0; i < b.N; i++ {
 45					if !historyIndexCurrent(brainDir, manifest) {
 46						b.Fatal("unchanged history unexpectedly stale")
 47					}
 48				}
 49			})
 50		}
 51	}
 52	
 53	func BenchmarkHistoryTranscriptRefreshPaired(b *testing.B) {
 54		for _, fileCount := range []int{48, 512} {
 55			b.Run(fmt.Sprintf("%d-files", fileCount), func(b *testing.B) {
 56				brainDir, corpusBytes := historyRefreshBenchmarkFixture(b, fileCount)
 57				cachePath := filepath.Join(brainDir, filepath.FromSlash(historyScanCachePath))
 58				now := time.Date(2026, 7, 17, 12, 0, 0, 0, time.UTC)
 59				var hashThenScan, singleRead time.Duration
 60				run := func(single bool) {
 61					if err := os.Remove(cachePath); err != nil && !os.IsNotExist(err) {
 62						b.Fatal(err)
 63					}
 64					start := time.Now()
 65					if single {
 66						if _, _, err := buildBrainHistoryIndex(brainDir, now, nil); err != nil {
 67							b.Fatal(err)
 68						}
 69						singleRead += time.Since(start)
 70						return
 71					}
 72					if _, _, err := buildBrainHistoryIndexHashThenScanReference(brainDir, now); err != nil {
 73						b.Fatal(err)
 74					}
 75					hashThenScan += time.Since(start)
 76				}
 77	
 78				b.ResetTimer()
 79				for i := 0; i < b.N; i++ {
 80					// Alternate order so either implementation sees each short-lived
 81					// machine-load and filesystem-cache advantage equally.
 82					if i%2 == 0 {
 83						run(false)
 84						run(true)
 85					} else {
 86						run(true)
 87						run(false)
 88					}
 89				}
 90				b.StopTimer()
 91				b.ReportMetric(float64(hashThenScan.Nanoseconds())/float64(b.N), "hash-scan-ns/op")
 92				b.ReportMetric(float64(singleRead.Nanoseconds())/float64(b.N), "single-read-ns/op")
 93				b.ReportMetric(float64(corpusBytes*2), "hash-scan-transcript-B/op")
 94				b.ReportMetric(float64(corpusBytes), "single-read-transcript-B/op")
 95			})
 96		}
 97	}
 98	
 99	func historyRefreshBenchmarkFixture(tb testing.TB, fileCount int) (string, int64) {
100		tb.Helper()
101		brainDir := tb.TempDir()
102		sessionsDir := filepath.Join(brainDir, exportSessionsDirectory, "main")
103		if err := os.MkdirAll(sessionsDir, 0o700); err != nil {
104			tb.Fatal(err)
105		}
106		// Each transcript is about 64 KiB. Most lines are intentionally irrelevant
107		// so the fixture exercises transcript I/O without turning this into a JSON
108		// classification benchmark.
109		padding := `{"type":"event_msg","payload":{"type":"usage","detail":"` + strings.Repeat("x", 4000) + `"}}` + "\n"
110		var corpusBytes int64
111		sessions := make([]exportSession, 0, fileCount)
112		for i := 0; i < fileCount; i++ {
113			content := strings.Repeat(padding, 16) + fmt.Sprintf(
114				`{"type":"agent_message","message":"Decision: retain synthetic history fixture %04d."}`+"\n", i,
115			)
116			name := fmt.Sprintf("20260717T%06dZ-session-%04d.jsonl", i, i)
117			path := filepath.Join(sessionsDir, name)
118			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
119				tb.Fatal(err)
120			}
121			corpusBytes += int64(len(content))
122			sessions = append(sessions, exportSession{
123				SessionID:      fmt.Sprintf("session-%04d", i),
124				Branch:         "main",
125				TranscriptPath: filepath.ToSlash(filepath.Join(exportSessionsDirectory, "main", name)),
126			})
127		}
128		now := time.Date(2026, 7, 17, 12, 0, 0, 0, time.UTC)
129		manifest := exportManifest{
130			SchemaVersion: brainManifestSchemaVersion,
131			GeneratedAt:   now,
132			DefaultBranch: "main",
133			Sources: &brainSources{Sessions: &sessionSourceManifest{
134				GeneratedAt:   now,
135				DefaultBranch: "main",
136				Sessions:      sessions,
137			}},
138		}
139		if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
140			tb.Fatal(err)
141		}
142		return brainDir, corpusBytes
143	}

