 19	// TestHistoryTranscriptSingleReadYieldsDigestAndRecords locks the single-read
 20	// property that scanHistoryFileWithContentSHA used to provide: one bounded,
 21	// descriptor-rooted read produces BOTH the verified content digest and the
 22	// parsed records, so a same-path rewrite between hashing and parsing cannot
 23	// produce a digest of one generation and records of another.
 24	func TestHistoryTranscriptSingleReadYieldsDigestAndRecords(t *testing.T) {
 25		document := `{
 26	  "messages": [
 27	    {"info":{"role":"assistant"},"parts":[{"type":"text","text":"Decision: retain document parsing."}]}
 28	  ]
 29	}`
 30		cases := []struct {
 31			name        string
 32			ext         string
 33			content     string
 34			wantSummary string
 35			wantScanErr bool
 36		}{
 37			{name: "jsonl", ext: ".jsonl", content: `{"type":"agent_message","message":"Decision: retain JSONL parsing."}` + "\n", wantSummary: "Decision: retain JSONL parsing."},
 38			{name: "document", ext: ".json", content: document, wantSummary: "Decision: retain document parsing."},
 39			{name: "markdown", ext: ".md", content: "Decision: retain markdown parsing.\n", wantSummary: "Decision: retain markdown parsing."},
 40			{name: "document-shaped fallback", ext: ".md", content: "{\nDecision: retain bounded fallback parsing.\n", wantSummary: "Decision: retain bounded fallback parsing."},
 41			{name: "oversized line", ext: ".txt", content: "Decision: " + strings.Repeat("x", historyMaxLineBytes+1) + "\n", wantScanErr: true},
 42		}
 43		for _, tc := range cases {
 44			t.Run(tc.name, func(t *testing.T) {
 45				brainDir := t.TempDir()
 46				rel := "sessions/main/session" + tc.ext
 47				full := filepath.Join(brainDir, filepath.FromSlash(rel))
 48				if err := os.MkdirAll(filepath.Dir(full), 0o700); err != nil {
 49					t.Fatal(err)
 50				}
 51				if err := os.WriteFile(full, []byte(tc.content), 0o600); err != nil {
 52					t.Fatal(err)
 53				}
 54				inventory, err := collectHistorySessionInventory(context.Background(), brainDir)
 55				if err != nil {
 56					t.Fatal(err)
 57				}
 58				defer inventory.Close()
 59				if len(inventory.files) != 1 {
 60					t.Fatalf("inventory = %d files, want 1", len(inventory.files))
 61				}
 62				file := inventory.files[0]
 63				content, digest, err := readHistorySessionInventoryFile(context.Background(), inventory, file)
 64				if err != nil {
 65					t.Fatalf("read: %v", err)
 66				}
 67				sum := sha256.Sum256([]byte(tc.content))
 68				if want := "sha256:" + hex.EncodeToString(sum[:]); digest != want {
 69					t.Fatalf("digest = %q, want %q", digest, want)
 70				}
 71				records, _, warnings, ok := scanSessionFileReaderRecords(context.Background(), bytes.NewReader(content), file.Path, file.Rel)
 72				if tc.wantScanErr {
 73					if ok || len(warnings) == 0 || !strings.Contains(strings.Join(warnings, " "), "token too long") {
 74						t.Fatalf("oversized scan = ok:%v warnings:%v, want a token-too-long refusal", ok, warnings)
 75					}
 76					return
 77				}
 78				if !ok {
 79					t.Fatalf("scan failed: %v", warnings)
 80				}
 81				found := false
 82				for _, record := range records {
 83					if record.Summary == tc.wantSummary {
 84						found = true
 85					}
 86				}
 87				if !found {
 88					t.Fatalf("records missing %q: %#v", tc.wantSummary, records)
 89				}
 90			})
 91		}
 92	}
