191			t.Fatalf("single-read source changed\ngot:  %#v\nwant: %#v", gotSource, wantSource)
192		}
193		if len(progress) < 2 || progress[0][0] != 0 || progress[0][1] == 0 || progress[len(progress)-1] != [2]int{progress[0][1], progress[0][1]} {
194			t.Fatalf("single-read progress = %v", progress)
195		}
196		if err := publishHistoryComparisonIndex(storage.BrainDir, gotIndex, gotSource); err != nil {
197			t.Fatalf("publish single-read: %v", err)
198		}
199		gotPacket := runBrainBriefRawHistoryEndToEnd(t, fixture, brainBriefRawHistoryMatchesObserved)
200		if gotPacket != wantPacket {
201			t.Fatalf("brain brief packet changed after single-read history build\ngot:\n%s\nwant:\n%s", gotPacket, wantPacket)
202		}
203	}
