205	// buildBrainHistoryIndexHashThenScanReference pins the pre-optimization
206	// behavior: hash every safe file during collection, then reopen changed files
207	// for parsing. It intentionally omits the scan cache so the comparison covers a
208	// full rebuild.
209	func buildBrainHistoryIndexHashThenScanReference(outputDir string, now time.Time) (historyIndex, *historySourceManifest, error) {
210		index := historyIndex{GeneratedAt: now}
211		files, err := collectHistorySessionDigests(context.Background(), outputDir, nil)
212		if err != nil {
213			return index, nil, err
214		}
215		transcriptsFingerprint := historyTranscriptFilesFingerprint(files)
216		manifest, _ := loadBrainManifest(outputDir)
217		branchByPath := historyBranchByTranscriptPath(manifest)
218		newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
219		seenDecisions := map[string]struct{}{}
220		for _, file := range files {
221			rel, relErr := filepath.Rel(outputDir, file.Path)
222			if relErr != nil {
223				rel = file.Path
224			}
225			rel = filepath.ToSlash(rel)
226			records, scanErr := scanHistoryFileHashThenScanReference(outputDir, file.Path)
227			if scanErr != nil {
228				index.Warnings = append(index.Warnings, scanErr.Error())
229				continue
230			}
231			newCache.Files[rel] = historyScanCacheEntry{ContentDigest: file.ContentDigest, Records: records}
232			records = annotateHistoryRecordBranches(records, rel, branchByPath)
233			for _, record := range records {
234				if record.Kind == "decision" {
235					dedupeKey := normalizeHistorySearchText(record.Summary)
236					if _, ok := seenDecisions[dedupeKey]; ok {
237						continue
238					}
239					seenDecisions[dedupeKey] = struct{}{}
240				}
241				index.Records = append(index.Records, record)
242			}
243		}
244		saveHistoryScanCache(outputDir, newCache)
245		sort.Slice(index.Records, func(i, j int) bool {
246			if index.Records[i].Kind != index.Records[j].Kind {
247				return index.Records[i].Kind < index.Records[j].Kind
248			}
249			if index.Records[i].Path != index.Records[j].Path {
250				return index.Records[i].Path < index.Records[j].Path
251			}
252			return index.Records[i].Line < index.Records[j].Line
253		})
254		source := &historySourceManifest{
255			GeneratedAt:            now,
256			IndexPath:              historyIndexPath,
257			SessionsFingerprint:    brainSessionsFingerprint(outputDir),
258			TranscriptsFingerprint: transcriptsFingerprint,
259			Records:                len(index.Records),
260			Warnings:               append([]string(nil), index.Warnings...),
261		}
262		for _, record := range index.Records {
263			switch record.Kind {
264			case "decision":
265				source.Decisions++
266			case "learning":
267				source.Learnings++
268			case "validation":
269				source.Validations++
270			case "tool_call":
271				source.ToolCalls++
272			case "code_fact":
273				source.CodeFacts++
274			}
275		}
276		return index, source, nil
277	}
278	
279	func scanHistoryFileHashThenScanReference(outputDir, path string) ([]historyRecord, error) {
280		f, err := os.Open(path)
281		if err != nil {
282			return nil, err
283		}
284		defer f.Close()
285		rel, _ := filepath.Rel(outputDir, path)
286		rel = filepath.ToSlash(rel)
287		if records, isDocument, err := scanDocumentHistoryFileHashThenScanReference(f, rel); err != nil {
288			return nil, err
289		} else if isDocument {
290			return records, nil
291		}
292		if _, err := f.Seek(0, io.SeekStart); err != nil {
293			return nil, err
294		}
295		return scanHistoryLines(context.Background(), rel, filepath.Ext(path), f)
296	}
297	
298	func scanDocumentHistoryFileHashThenScanReference(f *os.File, rel string) ([]historyRecord, bool, error) {
299		probe := make([]byte, 4096)
300		n, readErr := f.Read(probe)
301		if readErr != nil && readErr != io.EOF {
302			return nil, false, readErr
303		}
304		firstLine, _, _ := strings.Cut(strings.TrimSpace(string(probe[:n])), "\n")
305		if !strings.HasPrefix(firstLine, "{") || json.Valid([]byte(firstLine)) {
306			return nil, false, nil
307		}
308		data, err := safeReadAll(io.MultiReader(bytes.NewReader(probe[:n]), f), maxDocumentTranscriptBytes, "document transcript "+rel)
309		if err != nil {
310			return nil, false, err
311		}
312		messages, ok := parseDocumentConversation(string(data))
313		if !ok {
314			return nil, false, nil
315		}
316		return historyDocumentRecords(rel, messages), true, nil
317	}
318	
319	func publishHistoryComparisonIndex(brainDir string, index historyIndex, source *historySourceManifest) error {
320		data, err := json.MarshalIndent(index, "", "  ")
321		if err != nil {
322			return err
323		}
324		data = append(data, '\n')
325		publishedSource := *source
326		publishedSource.IndexBytes = int64(len(data))
327		publishedSource.IndexSHA256 = historyIndexBytesFingerprint(data)
328		publishedSource.RecordsFingerprint = historyRecordsFingerprint(index.Records)
329		if err := writeBrainRelativeFileAtomic(brainDir, historyIndexPath, data, 0o600); err != nil {
330			return err
331		}
332		manifest, err := loadBrainManifest(brainDir)
333		if err != nil {
334			return err
335		}
336		if manifest.Sources == nil {
337			manifest.Sources = &brainSources{}
338		}
339		manifest.Sources.History = &publishedSource
340		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
341			return err
342		}
343		// Exercise packet generation from a freshly derived FTS index in both arms.
344		for _, suffix := range []string{"", "-shm", "-wal"} {
345			if err := os.Remove(historyFTSDBPath(brainDir) + suffix); err != nil && !os.IsNotExist(err) {
346				return err
347			}
348		}
349		return nil
350	}

