205	// buildBrainHistoryIndexHashThenScanReference pins the pre-optimization
206	// behavior: hash every safe file during collection, then reopen changed files
207	// for parsing. It intentionally omits the scan cache so the comparison covers a
208	// full rebuild.
209	func buildBrainHistoryIndexHashThenScanReference(outputDir string, now time.Time) (historyIndex, *historySourceManifest, error) {
210		index := historyIndex{GeneratedAt: now}
211		files, err := collectHistorySessionDigests(context.Background(), outputDir, nil)
212		if err != nil {
213			return index, nil, err
214		}
215		transcriptsFingerprint := historyTranscriptFilesFingerprint(files)
216		manifest, _ := loadBrainManifest(outputDir)
217		branchByPath := historyBranchByTranscriptPath(manifest)
218		newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
219		seenDecisions := map[string]struct{}{}
220		for _, file := range files {
221			rel, relErr := filepath.Rel(outputDir, file.Path)
222			if relErr != nil {
223				rel = file.Path
224			}
225			rel = filepath.ToSlash(rel)
226			records, scanErr := scanHistoryFileHashThenScanReference(outputDir, file.Path)
227			if scanErr != nil {
228				index.Warnings = append(index.Warnings, scanErr.Error())
229				continue
230			}
231			newCache.Files[rel] = historyScanCacheEntry{ContentDigest: file.ContentDigest, Records: records}
232			records = annotateHistoryRecordBranches(records, rel, branchByPath)
233			for _, record := range records {
234				if record.Kind == "decision" {
235					dedupeKey := normalizeHistorySearchText(record.Summary)
236					if _, ok := seenDecisions[dedupeKey]; ok {
237						continue
238					}
239					seenDecisions[dedupeKey] = struct{}{}
240				}
241				index.Records = append(index.Records, record)
242			}
243		}
244		saveHistoryScanCache(outputDir, newCache)
245		sort.Slice(index.Records, func(i, j int) bool {
246			if index.Records[i].Kind != index.Records[j].Kind {
247				return index.Records[i].Kind < index.Records[j].Kind
248			}
249			if index.Records[i].Path != index.Records[j].Path {
250				return index.Records[i].Path < index.Records[j].Path
251			}
252			return index.Records[i].Line < index.Records[j].Line
253		})
254		source := &historySourceManifest{
255			GeneratedAt:            now,
256			IndexPath:              historyIndexPath,
257			SessionsFingerprint:    brainSessionsFingerprint(outputDir),
258			TranscriptsFingerprint: transcriptsFingerprint,
259			Records:                len(index.Records),
260			Warnings:               append([]string(nil), index.Warnings...),
261		}
262		for _, record := range index.Records {
263			switch record.Kind {
264			case "decision":
265				source.Decisions++
266			case "learning":
267				source.Learnings++
268			case "validation":
269				source.Validations++
270			case "tool_call":
271				source.ToolCalls++
272			case "code_fact":
273				source.CodeFacts++
274			}
275		}
276		return index, source, nil
277	}
