320		data, err := json.MarshalIndent(index, "", "  ")
321		if err != nil {
322			return err
323		}
324		data = append(data, '\n')
325		publishedSource := *source
326		publishedSource.IndexBytes = int64(len(data))
327		publishedSource.IndexSHA256 = historyIndexBytesFingerprint(data)
328		publishedSource.RecordsFingerprint = historyRecordsFingerprint(index.Records)
329		if err := writeBrainRelativeFileAtomic(brainDir, historyIndexPath, data, 0o600); err != nil {
330			return err
331		}
332		manifest, err := loadBrainManifest(brainDir)
333		if err != nil {
334			return err
335		}
336		if manifest.Sources == nil {
337			manifest.Sources = &brainSources{}
338		}
339		manifest.Sources.History = &publishedSource
340		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
341			return err
342		}
343		// Exercise packet generation from a freshly derived FTS index in both arms.
344		for _, suffix := range []string{"", "-shm", "-wal"} {
345			if err := os.Remove(historyFTSDBPath(brainDir) + suffix); err != nil && !os.IsNotExist(err) {
346				return err
347			}
348		}
