    94	// TestHistoryTranscriptAggregateFingerprintIsStableAndContentBound locks the
    95	// transcripts fingerprint: it commits the exact included set, is independent of
    96	// enumeration order, and changes when any transcript's bytes change.
    97	func TestHistoryTranscriptAggregateFingerprintIsStableAndContentBound(t *testing.T) {
    98		brainDir := t.TempDir()
    99		document := "{\n  \"messages\": [\n    {\"info\":{\"role\":\"assistant\"},\"parts\":[{\"type\":\"text\",\"text\":\"Decision: retain document parsing.\"}]}\n  ]\n}"
   100		contents := map[string]string{
   101			"a.jsonl": `{"type":"agent_message","message":"Decision: retain JSONL parsing."}` + "\n",
   102			"b.json":  document,
   103			"c.md":    "Decision: retain markdown parsing.\n",
   104			"d.md":    "{\nDecision: retain bounded fallback parsing.\n",
   105		}
   106		dir := filepath.Join(brainDir, "sessions", "main")
   107		if err := os.MkdirAll(dir, 0o700); err != nil {
   108			t.Fatal(err)
   109		}
   110		for name, content := range contents {
   111			if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o600); err != nil {
   112				t.Fatal(err)
   113			}
   114		}
   115		files, err := collectHistorySessionDigests(context.Background(), brainDir, nil)
   116		if err != nil {
   117			t.Fatalf("collect: %v", err)
   118		}
   119		if len(files) != len(contents) {
   120			t.Fatalf("collected %d files, want %d", len(files), len(contents))
   121		}
   122		first := historyTranscriptFilesFingerprint(files)
   123		if !validHistorySHA256(first) {
   124			t.Fatalf("fingerprint = %q, want a sha256", first)
   125		}
   126		// Enumeration order must not matter.
   127		shuffled := append([]historySessionFile(nil), files...)
   128		sort.Slice(shuffled, func(i, j int) bool { return shuffled[i].Rel > shuffled[j].Rel })
   129		if got := historyTranscriptFilesFingerprint(shuffled); got != first {
   130			t.Fatalf("fingerprint depends on order: %q vs %q", got, first)
   131		}
   132		// A single changed byte must change it.
   133		if err := os.WriteFile(filepath.Join(dir, "c.md"), []byte("Decision: retain markdown parsing!\n"), 0o600); err != nil {
   134			t.Fatal(err)
   135		}
   136		changed, err := collectHistorySessionDigests(context.Background(), brainDir, nil)
   137		if err != nil {
   138			t.Fatal(err)
   139		}
   140		if got := historyTranscriptFilesFingerprint(changed); got == first {
   141			t.Fatal("fingerprint survived a transcript content change")
   142		}
   143		// A missing digest must refuse to produce a fingerprint at all.
   144		partial := append([]historySessionFile(nil), files...)
   145		partial[0].ContentDigest = ""
   146		if got := historyTranscriptFilesFingerprint(partial); got != "" {
   147			t.Fatalf("fingerprint over an unverified set = %q, want empty", got)
   148		}
   149	}
