   279	func scanHistoryFileHashThenScanReference(outputDir, path string) ([]historyRecord, error) {
   280		f, err := os.Open(path)
   281		if err != nil {
   282			return nil, err
   283		}
   284		defer f.Close()
   285		rel, _ := filepath.Rel(outputDir, path)
   286		rel = filepath.ToSlash(rel)
   287		if records, isDocument, err := scanDocumentHistoryFileHashThenScanReference(f, rel); err != nil {
   288			return nil, err
   289		} else if isDocument {
   290			return records, nil
   291		}
   292		if _, err := f.Seek(0, io.SeekStart); err != nil {
   293			return nil, err
   294		}
   295		return scanHistoryLines(context.Background(), rel, filepath.Ext(path), f)
   296	}
   297	
   298	func scanDocumentHistoryFileHashThenScanReference(f *os.File, rel string) ([]historyRecord, bool, error) {
   299		probe := make([]byte, 4096)
   300		n, readErr := f.Read(probe)
   301		if readErr != nil && readErr != io.EOF {
   302			return nil, false, readErr
   303		}
   304		firstLine, _, _ := strings.Cut(strings.TrimSpace(string(probe[:n])), "\n")
   305		if !strings.HasPrefix(firstLine, "{") || json.Valid([]byte(firstLine)) {
   306			return nil, false, nil
   307		}
   308		data, err := safeReadAll(io.MultiReader(bytes.NewReader(probe[:n]), f), maxDocumentTranscriptBytes, "document transcript "+rel)
   309		if err != nil {
   310			return nil, false, err
   311		}
   312		messages, ok := parseDocumentConversation(string(data))
   313		if !ok {
   314			return nil, false, nil
   315		}
   316		return historyDocumentRecords(rel, messages), true, nil
   317	}
