121	func TestHistoryVecStoreRoundtrip(t *testing.T) {
122		brainDir := t.TempDir()
123		store, ok := newHistoryVectorStore(brainDir, "model-a", 2)
124		if !ok {
125			t.Fatal("brain_cgo build must provide the history vector store")
126		}
127	
128		// Fresh store: no ids yet.
129		if _, ok := store.ids(); ok {
130			t.Fatal("a store that was never written must report ok=false")
131		}
132	
133		if err := store.upsert(map[string][]float32{
134			"r1": {1, 0},
135			"r2": {0, 1},
136		}, nil); err != nil {
137			t.Fatal(err)
138		}
139		ids, ok := store.ids()
140		if !ok || len(ids) != 2 {
141			t.Fatalf("ids after upsert: ok=%v len=%d", ok, len(ids))
142		}
143	
144		// KNN: query along r1's direction must score r1 ~1 and r2 ~0.
145		scores, ok := store.knnCos([]float32{1, 0}, 10)
146		if !ok {
147			t.Fatal("knnCos must succeed on a populated store")
148		}
149		if scores["r1"] < 0.99 || scores["r2"] > 0.01 {
150			t.Fatalf("cosine scores wrong: %v", scores)
151		}
152	
153		// Re-adding a known id is a no-op; dropping removes both row and vector.
154		if err := store.upsert(map[string][]float32{"r1": {0, 1}}, []string{"r2"}); err != nil {
155			t.Fatal(err)
156		}
157		ids, _ = store.ids()
158		if len(ids) != 1 {
159			t.Fatalf("after drop: %v", ids)
160		}
161		scores, ok = store.knnCos([]float32{1, 0}, 10)
162		if !ok || scores["r1"] < 0.99 {
163			t.Fatalf("re-add of a known id must not overwrite its vector: %v (ok=%v)", scores, ok)
164		}
165		if _, present := scores["r2"]; present {
166			t.Fatal("dropped id must leave the KNN result")
167		}
168	
169		// A different model/dim sees a mismatched store: ids ok=false (sync treats
170		// as empty and rebuilds), and the first upsert resets the schema.
171		other, _ := newHistoryVectorStore(brainDir, "model-b", 3)
172		if _, ok := other.ids(); ok {
173			t.Fatal("model mismatch must read as no store")
174		}
175		if err := other.upsert(map[string][]float32{"r9": {1, 0, 0}}, nil); err != nil {
