310	// TestRankConversationFusedSemanticArmEndToEnd exercises the OPEN fused path
311	// against the real vec0 store with a deterministic fusion-eligible embedder:
312	// a term-disjoint exchange (no lexical overlap with the query) must be
313	// reachable through the semantic arm, and lexical hits must survive fusion.
314	func TestRankConversationFusedSemanticArmEndToEnd(t *testing.T) {
315		brainDir := t.TempDir()
316		semanticSummary := "term disjoint note about connection pooling"
317		lexicalSummary := "deploy pipeline alpha rollback rationale"
318		index := historyIndex{
319			GeneratedAt: time.Date(2026, 8, 7, 0, 0, 0, 0, time.UTC),
320			Records: []historyRecord{
321				{ID: conversationIDPrefix + "lex", Kind: conversationKind, SessionID: "s1",
322					Path: "sessions/main/a.jsonl", Line: 1, Summary: lexicalSummary},
323				{ID: conversationIDPrefix + "sem", Kind: conversationKind, SessionID: "s2",
324					Path: "sessions/main/b.jsonl", Line: 3, Summary: semanticSummary},
325				{ID: conversationIDPrefix + "far", Kind: conversationKind, SessionID: "s3",
326					Path: "sessions/main/c.jsonl", Line: 5, Summary: "unrelated chatter"},
327				{ID: "history:d1", Kind: "decision", Summary: "deploy pipeline decision must stay out"},
328			},
329		}
330		query := "deploy pipeline alpha"
331		e := &fakeFusionEmbedder{vecs: map[string][]float32{
332			query:               {0, 1},
333			semanticSummary:     {0, 1}, // cosine 1.0 with the query, zero lexical overlap
334			lexicalSummary:      {1, 0}, // lexically strong, semantically orthogonal
335			"unrelated chatter": {1, 0},
336		}}
337		// The store identity carries the embedding-text scheme version (reqw1);
338		// query-time lookups use the same versioned id.
339		store, ok := newConversationVectorStore(brainDir, conversationVectorModelID(e.ID()), e.Dim())
340		if !ok {
341			t.Fatal("conversation store unavailable on brain_cgo build")
342		}
343		if _, _, _, err := syncConversationVectors(store, index, e, nil); err != nil {
344			t.Fatalf("sync: %v", err)
345		}
346		markVectorGenerationCurrentForTest(t, brainDir, e)
347	
348		fused, _, ok := rankConversationFused(brainDir, index, query, 10, e, nil)
349		if !ok || len(fused) == 0 {
350			t.Fatalf("fused: ok=%v len=%d", ok, len(fused))
351		}
352		got := map[string]bool{}
353		for _, s := range fused {
354			got[s.Record.ID] = true
355			if s.Record.Kind != conversationKind {
356				t.Fatalf("non-exchange leaked through fusion: %+v", s.Record)
357			}
358		}
359		if !got[conversationIDPrefix+"lex"] {
360			t.Fatalf("lexical hit lost in fusion: %v", got)
361		}
362		if !got[conversationIDPrefix+"sem"] {
363			t.Fatalf("term-disjoint semantic hit not reachable through fusion: %v", got)
364		}
365	
366		// Explicit vector mode over the same store: semantic-only, best-first.
367		scores := conversationSemanticScores(brainDir, e, query, 10, false)
368		if len(scores) == 0 {
369			t.Fatal("conversationSemanticScores returned nothing with a populated store")
370		}
371		ranked := rankConversationSemantic(index, scores, 10)
372		if len(ranked) == 0 || ranked[0].Record.ID != conversationIDPrefix+"sem" {
373			t.Fatalf("vector mode order wrong: %+v", ranked)
374		}
