187	// TestRankHistoryFusedSemanticRescue is the capstone result in miniature: a
188	// record that shares no usable lexical term with the query is unreachable for
189	// BM25 but lives next to the query in vector space; with the gate open and
190	// vectors synced, the fused ranking surfaces both it and the lexical hit.
191	func TestRankHistoryFusedSemanticRescue(t *testing.T) {
192		brainDir := t.TempDir()
193		index := historyIndex{GeneratedAt: time.Now(), Records: []historyRecord{
194			{ID: "lex", Kind: "decision", Path: "sessions/main/s1.jsonl", Line: 1, Summary: "embeddings backend uses model2vec"},
195			{ID: "sem", Kind: "decision", Path: "sessions/main/s1.jsonl", Line: 5, Summary: "vector similarity drives recall ranking"},
196			{ID: "off", Kind: "decision", Path: "sessions/main/s2.jsonl", Line: 2, Summary: "progress output goes to stderr"},
197		}}
198		e := &fakeFusionEmbedder{vecs: map[string][]float32{
199			"embeddings backend uses model2vec":       {1, 0},
200			"vector similarity drives recall ranking": {0.1, 0.995},
201			"progress output goes to stderr":          {1, 0},
202			"embeddings backend":                      {0.1, 0.995}, // query lands on "sem"
203		}}
204		store, ok := newHistoryVectorStore(brainDir, e.ID(), e.Dim())
205		if !ok {
206			t.Fatal("store unavailable")
207		}
208		if _, _, _, err := syncHistoryVectors(store, index, e, nil); err != nil {
209			t.Fatal(err)
210		}
211		markVectorGenerationCurrentForTest(t, brainDir, e)
212	
213		// Sanity: plain FTS does not surface "sem" for this query.
214		ftsOnly, ok := rankHistoryViaFTS(brainDir, index, "history", "embeddings backend", 5)
215		if !ok {
216			t.Fatal("FTS ranking unavailable")
217		}
218		for _, s := range ftsOnly {
219			if s.Record.ID == "sem" {
220				t.Fatal("fixture broken: the semantic record must be lexically unreachable")
221			}
222		}
223	
224		fused, ok := rankHistoryFused(brainDir, index, "history", "embeddings backend", 5, e)
225		if !ok {
226			t.Fatal("fused ranking unavailable with gate open and vectors synced")
227		}
228		got := map[string]bool{}
229		for _, s := range fused {
230			got[s.Record.ID] = true
231		}
232		if !got["sem"] {
233			t.Fatalf("fusion must rescue the semantically-near record; got %v", fused)
234		}
235		if !got["lex"] {
236			t.Fatalf("fusion must keep the lexical hit; got %v", fused)
237		}
238	}
