267	// vector store is a distinct vec0 file with its own identity: writes to one
268	// are invisible to the other, so general history KNN can never surface
269	// exchange vectors and vice versa.
270	func TestConversationVecStoreIsolatedFromHistoryStore(t *testing.T) {
