377	// TestRankConversationFusedFilteredCompleteness proves filtered-window completeness on the semantic
378	// and fused arms against the real vec0 store: an in-scope exchange that both
379	// arms rank far below a wall of out-of-scope candidates is still returned
380	// when a structured filter selects it, because filters reach candidate
381	// generation instead of trimming an already-bounded window.
382	func TestRankConversationFusedFilteredCompleteness(t *testing.T) {
383		brainDir := t.TempDir()
384		query := "lock timeout retry storm"
385		vecs := map[string][]float32{query: {0, 1}}
386		records := make([]historyRecord, 0, 41)
387		for i := 0; i < 40; i++ {
388			summary := fmt.Sprintf("lock timeout lock timeout retry storm attempt %02d", i)
389			vecs[summary] = []float32{0, 1} // cosine 1.0 with the query
390			records = append(records, historyRecord{
391				ID: fmt.Sprintf("%snoise%02d", conversationIDPrefix, i), Kind: conversationKind,
392				SessionID: "noise-sess", Path: "sessions/main/noise.jsonl", Line: i*2 + 1,
393				Summary: summary,
394			})
395		}
396		targetSummary := "one lock timeout observed in an unrelated renderer warmup trace"
397		vecs[targetSummary] = []float32{1, 0} // cosine 0 with the query
398		records = append(records, historyRecord{
399			ID: conversationIDPrefix + "target", Kind: conversationKind,
400			SessionID: "target-sess", Path: "sessions/release/target.jsonl", Line: 1,
401			Summary: targetSummary,
402		})
403		index := historyIndex{GeneratedAt: time.Date(2026, 8, 7, 0, 0, 0, 0, time.UTC), Records: records}
404		e := &fakeFusionEmbedder{vecs: vecs}
405		store, ok := newConversationVectorStore(brainDir, conversationVectorModelID(e.ID()), e.Dim())
406		if !ok {
407			t.Fatal("conversation store unavailable on brain_cgo build")
408		}
409		if _, _, _, err := syncConversationVectors(store, index, e, nil); err != nil {
410			t.Fatalf("sync: %v", err)
411		}
412		markVectorGenerationCurrentForTest(t, brainDir, e)
413	
414		pred := func(r historyRecord) bool { return r.SessionID == "target-sess" }
415	
416		// Adversarial property: without the filter, the target is nowhere near
417		// the top of the fused list at this limit.
418		unfiltered, _, ok := rankConversationFused(brainDir, index, query, 2, e, nil)
419		if !ok {
420			t.Fatal("unfiltered fused ranking unavailable")
421		}
422		for _, s := range unfiltered {
423			if s.Record.ID == conversationIDPrefix+"target" {
424				t.Fatal("fixture not adversarial: target ranked into unfiltered fused top-k")
425			}
426		}
427	
428		fused, complete, ok := rankConversationFused(brainDir, index, query, 2, e, pred)
429		if !ok || !complete {
430			t.Fatalf("filtered fused: ok=%v complete=%v", ok, complete)
431		}
432		if len(fused) != 1 || fused[0].Record.ID != conversationIDPrefix+"target" {
433			t.Fatalf("filtered fused must return exactly the in-scope hit: %+v", fused)
434		}
435	
436		// The exhaustive semantic neighborhood covers every stored vector, so the
437		// filtered vector arm also reaches the target despite its cosine 0.
438		scores := conversationSemanticScoresExhaustive(brainDir, e, query, false)
439		if _, ok := scores[conversationIDPrefix+"target"]; !ok {
440			t.Fatalf("exhaustive scores missed the in-scope vector: %d scores", len(scores))
441		}
442		semIndex := historyIndex{GeneratedAt: index.GeneratedAt, Records: filterHistoryRecords(index.Records, pred)}
443		ranked := rankConversationSemantic(semIndex, scores, 2)
444		if len(ranked) != 1 || ranked[0].Record.ID != conversationIDPrefix+"target" {
445			t.Fatalf("filtered vector arm must return the in-scope hit: %+v", ranked)
446		}
447	}
