449	// TestExclusionCleanupDeletesPopulatedConversationVectorStore is the
450	// vector-store canary: a real vec0 store holding embeddings for a
451	// tombstoned session's exchanges is deleted by the shared cleanup and the
452	// operation still verifies clean.
453	func TestExclusionCleanupDeletesPopulatedConversationVectorStore(t *testing.T) {
454		brainDir := writePrivacyFixture(t)
455		manifest, err := loadBrainManifest(brainDir)
456		if err != nil {
457			t.Fatal(err)
458		}
459		index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
460		if err != nil {
461			t.Fatal(err)
462		}
463		e := &fakeFusionEmbedder{vecs: map[string][]float32{}}
464		store, ok := newConversationVectorStore(brainDir, conversationVectorModelID(e.ID()), e.Dim())
465		if !ok {
466			t.Fatal("conversation store unavailable on brain_cgo build")
467		}
468		if _, _, _, err := syncConversationVectors(store, index, e, nil); err != nil {
469			t.Fatalf("sync: %v", err)
470		}
471		storePath := filepath.Join(brainDir, filepath.FromSlash(historyDirName), embedStoreDirName, conversationVecStoreFileNamePortable)
472		if _, err := os.Stat(storePath); err != nil {
473			t.Fatalf("populated store must exist before cleanup: %v", err)
474		}
475	
476		var plan sessionPurgePlan
477		if err := withBrainWriteLock(brainDir, func() error {
478			var planErr error
479			plan, planErr = buildSessionPurgePlan(brainDir, "secret-sess")
480			if planErr != nil {
481				return planErr
482			}
483			return executeSessionCleanup(brainDir, "secret-sess", plan, time.Now().UTC(), "test", true)
484		}); err != nil {
485			t.Fatalf("cleanup: %v", err)
486		}
487		listed := false
488		for _, artifact := range plan.DerivedStores {
489			if strings.HasSuffix(artifact.Path, conversationVecStoreFileNamePortable) {
490				listed = true
491			}
492		}
493		if !listed {
494			t.Fatalf("vector store missing from the cleanup inventory: %+v", plan.DerivedStores)
495		}
496		if _, err := os.Stat(storePath); !os.IsNotExist(err) {
497			t.Fatalf("vector store must be deleted by exclusion cleanup: %v", err)
498		}
499	}

