10	// TestHistoryVecStoreKnnAtScale guards the k = row-count KNN query at history
11	// corpus sizes: sqlite-vec's vec0 MATCH has internal limits the facts store
12	// never hits at its few-hundred-row scale.
13	func TestHistoryVecStoreKnnAtScale(t *testing.T) {
14		store, ok := newHistoryVectorStore(t.TempDir(), "scale-model", 4)
15		if !ok {
16			t.Fatal("store unavailable")
17		}
18		const n = 20000
19		batch := map[string][]float32{}
20		for i := 0; i < n; i++ {
21			batch[fmt.Sprintf("r%05d", i)] = []float32{float32(i%7 + 1), float32(i%11 + 1), float32(i%13 + 1), 1}
22			if len(batch) == 2048 {
23				if err := store.upsert(batch, nil); err != nil {
24					t.Fatal(err)
25				}
26				batch = map[string][]float32{}
27			}
28		}
29		if err := store.upsert(batch, nil); err != nil {
30			t.Fatal(err)
31		}
32		scores, ok := store.knnCos([]float32{1, 1, 1, 1}, 200)
33		if !ok {
34			t.Fatal("knnCos failed at 20k rows")
35		}
36		if len(scores) != 200 {
37			t.Fatalf("knnCos returned %d of the requested 200", len(scores))
38		}
39		// And a request far above vec0's MATCH k ceiling must clamp, not error.
40		scores, ok = store.knnCos([]float32{1, 1, 1, 1}, n)
41		if !ok {
42			t.Fatal("knnCos must clamp an over-ceiling k, not fail")
43		}
44		if len(scores) != vec0KnnMaxK {
45			t.Fatalf("over-ceiling k must clamp to %d, got %d", vec0KnnMaxK, len(scores))
46		}
47	}

