		synthesis string
	}{
		{name: "invented evidence", synthesis: `{"overview":{"text":"invented","evidence_ids":["conversation:not-in-fragments"]}}`},
		{name: "missing required citation", synthesis: `{"overview":{"text":"uncited"}}`},
	} {
