	}
	var payload struct {
		Receipt memoryOperationReceipt `json:"receipt"`
		Config  memoryConfig           `json:"config"`
	}
	if err := json.Unmarshal([]byte(out), &payload); err != nil || !payload.Receipt.DryRun || payload.Config.Abstracts.Provider != "codex" {
