func receiptHasProspectiveTransition(receipt memoryOperationReceipt) bool {
	for _, artifact := range receipt.Artifacts {
		if strings.HasPrefix(artifact.NewState, "would_") && artifact.NewState != artifact.PriorState {
			return true
		}
	}
	return false
}

