	brainDir := writePrivacyFixture(t)
	now := time.Date(2026, 8, 9, 12, 0, 0, 0, time.UTC)
	cutoff := now.Add(-24 * time.Hour)
	providerUnlock, err := acquireBrainPrivacySideEffectLock(brainDir)
