		_, err := fmt.Fprint(cmd.OutOrStdout(), "private abstract\n")
		return err
	}); err != nil {
		t.Fatal(err)
	}
	if privacyState.unlock == nil {
		t.Fatal("MCP output did not retain the privacy lock for the outer frame")
	}

