   140	// lookupGuideFlag resolves a long flag on a command or any of its parents
   141	// (persistent flags are inherited).
   142	func lookupGuideFlag(cmd *cobra.Command, name string) any {
   143		if f := cmd.Flags().Lookup(name); f != nil {
   144			return f
   145		}
   146		for parent := cmd.Parent(); parent != nil; parent = parent.Parent() {
   147			if f := parent.PersistentFlags().Lookup(name); f != nil {
   148				return f
   149			}
   150		}
   151		return nil
   152	}
