   459	// gitHardenHookRepo builds a repository carrying a live post-index-change hook
   460	// and returns the file that hook appends a line to on every execution.
   461	//
   462	// The hook is written straight to disk because git has no command that installs
   463	// one, and it writes only to that file: post-index-change inherits the caller's
   464	// stdout, so a chattier payload would corrupt the porcelain under test rather
   465	// than merely proving it ran.
   466	//
   467	// b.txt is the file the arming works on. gitHardenRepo leaves a.txt genuinely
   468	// modified, and git does not refresh the cached stat of a file whose content no
   469	// longer matches the index -- it has real work to report instead. The trigger
   470	// has to be a file that is still clean.
   471	func gitHardenHookRepo(t *testing.T) (repo, log string) {
   472		t.Helper()
   473		repo = gitHardenRepo(t)
   474		log = filepath.Join(t.TempDir(), "EXECUTIONS")
   475	
   476		hooks := filepath.Join(repo, ".git", "hooks")
   477		if err := os.MkdirAll(hooks, 0o755); err != nil {
   478			t.Fatal(err)
   479		}
   480		body := "#!/bin/sh\necho fired >> " + log + "\nexit 0\n"
   481		if err := os.WriteFile(filepath.Join(hooks, gitHardenHookName), []byte(body), 0o755); err != nil {
   482			t.Fatal(err)
   483		}
   484	
   485		if err := os.WriteFile(filepath.Join(repo, "b.txt"), []byte("clean\n"), 0o644); err != nil {
   486			t.Fatal(err)
   487		}
   488		// Staging b.txt alone keeps a.txt in the index exactly as HEAD has it, so
   489		// the commit does not swallow the worktree modification the other tests in
   490		// this file depend on.
   491		gitHardenRun(t, repo, "add", "b.txt")
   492		gitHardenRun(t, repo, "commit", "-qm", "armed")
   493		return repo, log
   494	}
