   175	func buildHistoryFTSV1Fixture(path string, index historyIndex) error {
   176		db, err := sql.Open(sqliteDriverName, path)
   177		if err != nil {
   178			return err
   179		}
   180		defer db.Close()
   181		if _, err := db.Exec(`CREATE VIRTUAL TABLE history_fts USING fts5(content, kind UNINDEXED, rec_order UNINDEXED, tokenize='porter unicode61')`); err != nil {
   182			return err
   183		}
   184		tx, err := db.Begin()
   185		if err != nil {
   186			return err
   187		}
   188		defer tx.Rollback()
   189		stmt, err := tx.Prepare(`INSERT INTO history_fts(content, kind, rec_order) VALUES (?, ?, ?)`)
   190		if err != nil {
   191			return err
