     9	// fuseTieDigests is an 8-way exact tie. sort.SliceStable leaves
    10	// comparator-equal elements in input order, and the input order of
    11	// fuseScoredRankLists is a Go map range, which is re-randomized on every
    12	// iteration. With an incomplete comparator a single call therefore has a
    13	// 1/8! (~1 in 40,320) chance of landing on the sorted order, so the assertion
    14	// below fails on effectively every run and certainly within the loop.
    15	var fuseTieDigests = []string{"d01", "d02", "d03", "d04", "d05", "d06", "d07", "d08"}
    16	
    17	func fuseTieLists(records []historyRecord) [][]scoredHistoryRecord {
    18		lists := make([][]scoredHistoryRecord, 0, len(records))
    19		for _, record := range records {
    20			// One record per list, all at rank 0: every entry earns the identical
    21			// RRF contribution, so score can never break the tie.
    22			lists = append(lists, []scoredHistoryRecord{{Record: record}})
    23		}
    24		return lists
    25	}
