    27	func fuseOrder(fused []scoredHistoryRecord, field func(historyRecord) string) string {
    28		parts := make([]string, len(fused))
    29		for i, s := range fused {
    30			parts[i] = field(s.Record)
    31		}
    32		return strings.Join(parts, " ")
    33	}
