    65	func TestHistorySessionOpenDoesNotBlockOnRegularToFIFOSwap(t *testing.T) {
    66		brainDir, err := os.MkdirTemp("/tmp", "eb-history-swap-")
    67		if err != nil {
    68			t.Fatal(err)
    69		}
    70		t.Cleanup(func() { _ = os.RemoveAll(brainDir) })
    71		dir := filepath.Join(brainDir, exportSessionsDirectory, "main")
    72		if err := os.MkdirAll(dir, 0o700); err != nil {
    73			t.Fatal(err)
    74		}
    75		target := filepath.Join(dir, "session.jsonl")
    76		if err := os.WriteFile(target, []byte("{}\n"), 0o600); err != nil {
    77			t.Fatal(err)
    78		}
    79		inventory, err := collectHistorySessionInventory(context.Background(), brainDir)
    80		if err != nil {
    81			t.Fatal(err)
    82		}
    83		defer inventory.Close()
    84		if len(inventory.files) != 1 {
    85			t.Fatalf("inventory files = %d", len(inventory.files))
    86		}
    87		originalHook := beforeHistorySessionDescriptorOpen
    88		swapped := false
    89		var swapErr error
    90		beforeHistorySessionDescriptorOpen = func(rel string) {
    91			if swapped || rel != inventory.files[0].Rel {
    92				return
    93			}
    94			swapped = true
    95			if swapErr = os.Rename(target, target+".old"); swapErr != nil {
    96				return
    97			}
    98			swapErr = unix.Mkfifo(target, 0o600)
    99		}
   100		t.Cleanup(func() { beforeHistorySessionDescriptorOpen = originalHook })
   101	
   102		done := make(chan error, 1)
   103		go func() {
   104			f, openErr := inventory.open(context.Background(), inventory.files[0])
   105			if f != nil {
   106				_ = f.Close()
   107			}
   108			done <- openErr
   109		}()
   110		select {
   111		case openErr := <-done:
   112			if swapErr != nil {
   113				t.Fatalf("swap transcript with FIFO: %v", swapErr)
   114			}
   115			if !swapped || !errors.Is(openErr, errHistorySessionInventoryDegraded) {
   116				t.Fatalf("swapped=%v open error=%v", swapped, openErr)
   117			}
   118		case <-time.After(2 * time.Second):
   119			t.Fatal("descriptor open blocked on raced FIFO")
   120		}
   121	}
