   123	func TestConversationExpansionRejectsBrainRootSwapAfterRead(t *testing.T) {
   124		parent := t.TempDir()
   125		brainDir := filepath.Join(parent, "brain")
   126		rel := "sessions/main/20260809T000000Z_root-swap.jsonl"
   127		body := strings.Join([]string{
   128			`{"type":"user","message":{"role":"user","content":[{"type":"text","text":"private request"}]}}`,
   129			`{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"private response"}]}}`,
   130			"",
