   139		record := historyRecord{Path: rel, Line: 1, EndLine: 2, SourceDigest: conversationDigest([]byte(body))}
   140	
   141		originalHook := beforeCanonicalHistoryTranscriptFinish
   142		beforeCanonicalHistoryTranscriptFinish = func() {
   143			detached := filepath.Join(parent, "detached-brain")
