188	func TestHistoryLegacyIdentityConcurrentMigrationPreservesNewerFields(t *testing.T) {
189		brainDir, legacy := writeLegacyHistoryIdentityFixture(t, ftsTestIndex())
190		_, identity := loadLegacyHistoryIdentityCandidate(t, brainDir, legacy)
191	
192		manifest, err := loadBrainManifest(brainDir)
193		if err != nil {
194			t.Fatal(err)
195		}
196		manifest.Sources.History.Warnings = []string{"newer concurrent warning"}
197		manifest.RepoKey = "gh/example/preserved"
198		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
199			t.Fatal(err)
200		}
201	
202		const workers = 24
203		start := make(chan struct{})
204		var wg sync.WaitGroup
205		for i := 0; i < workers; i++ {
206			wg.Add(1)
207			go func() {
208				defer wg.Done()
209				<-start
210				// A busy zero-wait lock is an expected best-effort miss; at least one
211				// contender will persist and every contender leaves newer fields alone.
212				_ = persistHistoryLegacyIdentity(brainDir, identity)
213			}()
214		}
215		close(start)
216		wg.Wait()
217		assertHistoryIdentityPersisted(t, brainDir, identity)
218		got, err := loadBrainManifest(brainDir)
219		if err != nil {
220			t.Fatal(err)
221		}
222		if got.RepoKey != "gh/example/preserved" || !reflect.DeepEqual(got.Sources.History.Warnings, []string{"newer concurrent warning"}) {
223			t.Fatalf("migration lost concurrent manifest fields: repo=%q warnings=%v", got.RepoKey, got.Sources.History.Warnings)
224		}
225	}
