327	func TestHistoryLegacyIdentityManifestReplacementIsAtomic(t *testing.T) {
328		brainDir, legacy := writeLegacyHistoryIdentityFixture(t, ftsTestIndex())
329		_, identity := loadLegacyHistoryIdentityCandidate(t, brainDir, legacy)
330		manifestPath := filepath.Join(brainDir, exportManifestFileName)
331		oldData, err := os.ReadFile(manifestPath)
332		if err != nil {
333			t.Fatal(err)
334		}
335	
336		stop := make(chan struct{})
337		errs := make(chan error, 1)
338		var wg sync.WaitGroup
339		readerCount := 8
340		if runtime.GOOS == "windows" {
341			// os.ReadFile opens without FILE_SHARE_DELETE on Windows. A tight set of
342			// overlapping readers can therefore prevent any atomic replacement at
343			// all; one yielding reader still proves every observed document is old
344			// or new while giving MoveFileEx a bounded replacement window.
345			readerCount = 1
346		}
347		for i := 0; i < readerCount; i++ {
348			wg.Add(1)
349			go func() {
350				defer wg.Done()
351				for {
352					select {
353					case <-stop:
354						return
355					default:
356					}
357					data, err := os.ReadFile(manifestPath)
358					if err != nil {
359						lower := strings.ToLower(err.Error())
360						if runtime.GOOS == "windows" && (os.IsPermission(err) || strings.Contains(lower, "being used by another process") || strings.Contains(lower, "sharing violation")) {
361							continue
362						}
363						select {
364						case errs <- err:
365						default:
366						}
367						return
368					}
369					var manifest exportManifest
370					if err := json.Unmarshal(data, &manifest); err != nil {
371						select {
372						case errs <- err:
373						default:
374						}
375						return
376					}
377					if runtime.GOOS == "windows" {
378						time.Sleep(time.Millisecond)
379					}
380				}
381			}()
382		}
383		if err := persistHistoryLegacyIdentity(brainDir, identity); err != nil {
384			close(stop)
385			wg.Wait()
386			t.Fatal(err)
387		}
388		close(stop)
389		wg.Wait()
390		select {
391		case err := <-errs:
392			t.Fatalf("reader observed non-atomic manifest: %v", err)
393		default:
394		}
395		newData, err := os.ReadFile(manifestPath)
396		if err != nil {
397			t.Fatal(err)
398		}
399		if bytes.Equal(oldData, newData) {
400			t.Fatal("migration did not replace legacy manifest")
401		}
402		if matches, err := filepath.Glob(filepath.Join(brainDir, "."+exportManifestFileName+".tmp-*")); err != nil || len(matches) != 0 {
