    40		var summaries []string
    41		var vecs [][]float32
    42		for _, r := range index.Records {
    43			if r.Kind == "decision" {
    44				summaries = append(summaries, r.Summary)
    45				vecs = append(vecs, e.Embed(r.Summary))
    46			}
    47		}
    48		t.Logf("embedder=%s  decision_records=%d", e.ID(), len(summaries))
    49	
    50		// Positives are paraphrases of topics this brain decided on; negatives are
    51		// unrelated. (Tuned for the entire-brain brain — the retrieval/embedding
    52		// meta-domain.) maxCos = best match any decision gets for the query.
    53		maxCos := func(q string) (float64, string) {
    54			qv := embedQ(q)
    55			best, bestIdx := -1.0, 0
    56			for i := range vecs {
    57				if c := cosineFloat32(qv, vecs[i]); c > best {
    58					best, bestIdx = c, i
    59				}
    60			}
    61			s := summaries[bestIdx]
    62			if len(s) > 70 {
    63				s = s[:70]
    64			}
    65			return best, s
    66		}
    67		type probe struct {
    68			label string
    69			max   float64
    70		}
    71		var pos, neg []probe
    72		for _, q := range []string{
    73			"reasons we picked one embedding approach over another",
    74			"tradeoffs of shipping native binaries to many machines",
    75			"why did we abandon the pure Go constraint",
    76			"how does reconcile decide to supersede a fact",
    77			"what is the precision control for history ranking",
    78		} {
    79			m, hit := maxCos(q)
    80			pos = append(pos, probe{q, m})
    81			t.Logf("POS %.3f  %q -> %q", m, q, hit)
    82		}
    83		for _, q := range []string{
    84			"fake metadata",
    85			"banana pancake breakfast recipe",
    86			"weather forecast for tomorrow in Berlin",
    87			"how to tune a guitar",
    88		} {
    89			m, _ := maxCos(q)
    90			neg = append(neg, probe{q, m})
    91			t.Logf("NEG %.3f  %q", m, q)
    92		}
    93		sort.Slice(pos, func(i, j int) bool { return pos[i].max < pos[j].max })
    94		sort.Slice(neg, func(i, j int) bool { return neg[i].max > neg[j].max })
    95		worstPos, bestNeg := pos[0].max, neg[0].max
    96		t.Logf("=== %s: worst positive=%.3f (%q)  best negative=%.3f (%q)  separated=%v ===",
    97			e.ID(), worstPos, pos[0].label, bestNeg, neg[0].label, worstPos > bestNeg)
    98	}

