    34	// memHistoryVecStore is an in-memory historyVectorStore so the sync logic is
    35	// testable on both builds (the real vec0 store exists only under brain_cgo).
    36	type memHistoryVecStore struct {
    37		vecs     map[string][]float32
    38		upserts  int
    39		knnCalls int
    40	}
    41	
    42	func newMemHistoryVecStore() *memHistoryVecStore {
    43		return &memHistoryVecStore{vecs: map[string][]float32{}}
    44	}
    45	
    46	func (m *memHistoryVecStore) ids() (map[string]struct{}, bool) {
    47		out := make(map[string]struct{}, len(m.vecs))
    48		for id := range m.vecs {
    49			out[id] = struct{}{}
    50		}
    51		return out, true
    52	}
    53	
    54	func (m *memHistoryVecStore) upsert(add map[string][]float32, drop []string) error {
    55		m.upserts++
    56		for _, id := range drop {
    57			delete(m.vecs, id)
    58		}
    59		for id, v := range add {
    60			m.vecs[id] = v
    61		}
    62		return nil
    63	}
    64	
    65	func (m *memHistoryVecStore) knnCos(qvec []float32, k int) (map[string]float64, bool) {
    66		m.knnCalls++
    67		if len(m.vecs) == 0 || k <= 0 {
    68			return nil, false
    69		}
    70		type sc struct {
    71			id  string
    72			cos float64
    73		}
    74		all := make([]sc, 0, len(m.vecs))
    75		for id, v := range m.vecs {
    76			all = append(all, sc{id, cosineFloat32(qvec, v)})
    77		}
    78		sort.Slice(all, func(a, b int) bool { return all[a].cos > all[b].cos })
    79		if len(all) > k {
    80			all = all[:k]
    81		}
    82		out := make(map[string]float64, len(all))
    83		for _, s := range all {
    84			out[s.id] = s.cos
    85		}
    86		return out, true
    87	}
